namespace Gameworld.Domain;

// The description and the lore of the variants of the default vocations, keyed by
// "vocation id/variant name". No doc describes a variant (docs/research/vocations.md only names
// them in its lines "Covers"), so both texts are written here. The description is the work of the
// variant and what a picture of the person shows, in a medieval world with some magic. The lore is
// its standing, its customs and its quarrels, with the races of docs/races-basis.md where one of
// them is known for the work.

public static partial class DefaultTexts
{
    internal static readonly Dictionary<string, (string Description, string Lore)> VocationVariants = new()
    {
        // farmer
        ["farmer/ploughman"] = ("Walks behind a heavy wooden plough and a team of oxen, one hand on the stilt and a goad in the other. Mud to the knee, a wool tunic and a straw hat.", "The best-paid hand on a manor, and the one who talks to the oxen more than to his wife. A straight furrow is a man's whole name in the village."),
        ["farmer/peasant"] = ("Works a few strips of the village field and owes days on the lord's land. A patched tunic, bare legs, a sickle or a hoe, and a bent back.", "Bound to the land he works, and the land to him: a lord may sell the manor, but not move the peasant off it. Midlanders count their villages by ploughs, not by people."),
        ["farmer/free farmer"] = ("Owns the land he ploughs and owes no lord a day's work. Better fed and better shod than a peasant, with a good knife at the belt and a timber house of his own.", "Sits in the assembly, bears arms and answers to the law alone. Northmen hold that a people is only as free as its farmers."),
        ["farmer/tenant"] = ("Farms rented land and pays for it in coin or grain at the quarter day. Seen with a loaded cart at the lord's barn, or counting sacks against a tally stick.", "A lease runs for a term of years or of lives, and the quarrels begin when it ends. A good tenant is one the lord forgets he has."),
        ["farmer/share-cropper"] = ("Works another's field with another's seed and keeps a share of the crop. The poorest of those who plough: thin, barefoot, with a borrowed hoe.", "Half the crop goes to the owner before the family eats. In a bad year the debt is carried over, and the children inherit it."),
        ["farmer/paddy farmer"] = ("Stands ankle-deep in a flooded field, bent double, setting green seedlings in rows. A wide conical hat, rolled-up trousers, and a water buffalo near by.", "Canal folk say the empire is a paddy field: it stands as long as every bank is mended by the one who stands on it."),
        ["farmer/rice farmer"] = ("Grows rice on terraces and banked fields, and minds the dykes and sluices that water them. Carries a sickle and sheaves of rice on a shoulder pole.", "On the lands of the Rainkeepers the water is shared by an old schedule, and the one who opens a sluice out of turn is judged by the whole village."),
        ["farmer/millet farmer"] = ("Sows millet and sorghum on dry ground with a short-handled hoe after the first rain. Stands among stalks taller than a person, by round granaries of mud and thatch.", "Sunlanders pour the first beer of the millet on the ground for those who cleared the field. The granary is the wife's, and nobody opens it without her."),
        ["farmer/yam farmer"] = ("Heaps earth into mounds with a broad hoe and stakes the yam vines that climb from them. Carries tubers as long as an arm to the yam barn.", "A man's standing is the size of his yam barn. The new yam is not eaten until the feast that opens it, however hungry the house is."),
        // gardener
        ["gardener/orchard keeper"] = ("Tends rows of fruit trees: prunes in winter, props laden boughs and picks from a ladder. A pruning knife, a basket on the arm and a straw hat.", "Halflings plant an apple tree at a birth and judge the grown child by the tree. An orchard is wassailed in midwinter with cider and noise."),
        ["gardener/vine dresser"] = ("Works a vineyard on a sunny slope: ties the vines to stakes, cuts them back with a hooked knife, and carries grapes in a tall basket on the back.", "A vineyard is planted for one's grandchildren. The vintage is the one harvest that a whole town turns out for, and is paid in drink."),
        ["gardener/olive grower"] = ("Keeps a grove of grey, twisted olive trees on terraces of dry stone. At harvest beats the branches with long poles over cloths spread on the ground.", "To cut down an enemy's olive trees is a crime in every law of the dry south, because it punishes people not yet born."),
        ["gardener/date gardener"] = ("Tends date palms in an oasis garden watered by small channels. Climbs the trunk with a rope sling to dust the flowers and cut the bunches.", "Saltroad folk say a palm must have its feet in water and its head in fire. A garden is inherited by the tree, and a single palm can have six owners."),
        ["gardener/spice grower"] = ("Grows pepper vines, ginger, cardamom or clove trees in shaded hill gardens. Dries the crop on mats in the sun, in a cloud of its scent.", "The growers have never seen the price their crop fetches at the far end of the road, and the merchants take care that they do not."),
        ["gardener/tea grower"] = ("Picks the young leaves from rows of low tea bushes on a misty hillside, into a basket on the back. A wide hat and quick fingers.", "Canal folk pick the first leaves before the spring rain and send them to the court. What the pickers drink is the dust that is left."),
        ["gardener/coffee grower"] = ("Tends coffee shrubs under shade trees on a highland slope, picks the red berries by hand and dries them on raised mats.", "The drink came down from the highlands with the scholars of the Saltroad folk, who wanted to stay awake over their books."),
        ["gardener/tobacco grower"] = ("Grows broad-leaved tobacco in neat plots and hangs the leaves in an airy barn to cure brown. Often seen with a clay pipe of the crop.", "Halflings grow the best leaf and name each field's crop like a vintage. Their elders settle disputes over a pipe, and nobody may speak until it is lit."),
        ["gardener/dye-plant grower"] = ("Grows woad, madder, weld or indigo for the dyers. Hands and forearms are stained blue, red or yellow to the elbow.", "A woad grower is known by blue hands at any market, and a town that lives by one dye plant guards its seed like coin."),
        ["gardener/silk grower"] = ("Keeps mulberry trees and feeds their leaves to trays of pale silkworms indoors. Reels the thread from cocoons floating in a pan of hot water.", "The Canal folk kept the worm a secret for a thousand years, on pain of death. The rooms are kept quiet: the worms are said to stop eating at a quarrel."),
        ["gardener/beekeeper"] = ("Keeps bees in straw skeps or hollow logs at the edge of a garden. Wears a veil of cloth over a wide hat and carries a smoking pot.", "The bees must be told of a death or a wedding in the house, or they leave. Stillfaces keep bees without smoke and are thought uncanny for it."),
        ["gardener/mushroom grower"] = ("Grows mushrooms on beds of dung and straw in cellars, caves and old mine galleries. Works by lamplight with a small knife and a shallow basket.", "Dwarves and Gnomes grew mushrooms in the dark through the Ashen Years, and have not forgotten who came begging at the gate."),
        ["gardener/seedsman"] = ("Raises plants for their seed, sorts it and sells it in small labelled bags. A neat stall of jars, sieves and paper packets.", "Gnomes keep seed lists that go back to the Old Realms and will sell any seed but the last of a kind."),
        ["gardener/grafter"] = ("Joins a twig of a good tree to the stock of a hardy one, binds it with bast and seals it with wax. Carries a small sharp knife and a bundle of cuttings.", "Gnome grafters set three kinds of apple on one tree for show. Elves call grafting a forced marriage and will not eat the fruit."),
        // herder
        ["herder/shepherd"] = ("Minds a flock of sheep on open pasture with a crook and a dog. A heavy cloak, a felt hat, a bag of bread and a horn or a pipe.", "Alone for weeks with the flock, the stars and a pipe. Half the songs of any people were made by shepherds, and half the prophets were shepherds first."),
        ["herder/cowherd"] = ("Drives the village cattle to pasture at dawn and home at dusk, with a long stick and a horn. Boots thick with mud and dung.", "Sunlanders count wealth, marriage and blood-price in cattle, and a herder knows each beast by name and by song."),
        ["herder/swineherd"] = ("Keeps a herd of bristly pigs in the wood and beats acorns down from the oaks for them in autumn. A long staff, a horn and a ragged tunic.", "The lowest of the herders in every tale, and the one who turns out to be a lost prince. Pannage in the lord's wood is paid for by the pig."),
        ["herder/goatherd"] = ("Follows a herd of goats over stony hillsides where nothing else can graze. Lean and sunburnt, with a staff, a sling and a waterskin.", "Dwarves keep goats on the high pastures above the hold and send their young up with them for a summer, to learn the sky."),
        ["herder/reindeer herder"] = ("Moves with a herd of reindeer between forest and tundra. Dressed in furs and embroidered wool, with a lasso, a sled and a tent of hides.", "The herd decides where the people go, and the herder follows. Asking the size of a herd is as rude as asking the weight of a purse."),
        ["herder/yak herder"] = ("Keeps shaggy yaks on high cold pasture above the tree line. A thick sheepskin coat, a felt hat, a sling, and a black tent of yak hair.", "Hearthbloods herd where no one else can stand the cold, and burn the dung to feed the fire outside as they feed the one within."),
        ["herder/nomad herder"] = ("Lives in a felt tent and moves with the herds by the season, on horseback. Owns only what a pack animal can carry, and counts wealth in heads.", "Grass riders say a man who builds a wall has already been conquered. The tent is the wife's, the herd is the family's, and the grass is no one's."),
        ["herder/dairymaid"] = ("Milks the cows morning and evening and churns the cream to butter. A wooden pail, a yoke over the shoulders, a three-legged stool and rolled sleeves.", "The one servant on a farm with a room that is kept clean. Milk turns in thunder, and when it turns without thunder someone is blamed for a look."),
        ["herder/cheesemaker"] = ("Curdles milk in a great kettle, presses the curd in wooden hoops and turns the wheels of cheese on the shelves of a cool cellar.", "Halflings age a wheel for each child born and cut it at the wedding. A cheese that old is a boast and a risk."),
        ["herder/horse breeder"] = ("Keeps mares and a stallion on good pasture and raises foals for sale. Judges a horse by its legs and teeth, and wears riding boots every day.", "Among the Grass riders a bloodline of horses is recited like a bloodline of khans, and is often longer."),
        ["herder/horse breaker"] = ("Tames young horses to the halter, the saddle and the cart, with a long rein in a round pen. Wiry and patient, and often limping.", "The gentle breakers are the ones people pay for, and the Stillfaces are the best of them: a horse cannot read fear on a face that never moves."),
        ["herder/camel breeder"] = ("Raises camels at the desert edge for milk, wool and the caravans. Robed and veiled against the dust, with a riding stick and a string of animals.", "Saltroad folk hold that a camel remembers every wrong and waits. A breeder sells the beast and keeps the right to its first calf."),
        // fisher
        ["fisher/sea fisher"] = ("Goes out in an open boat with nets and long lines, by sail and oar. Salt-stiff wool, an oiled leather apron, and hands scarred by line and hook.", "No whistling in the boat, no priest on the quay, no word for the animals of the land while at sea. Northmen name the boat before the child."),
        ["fisher/river fisher"] = ("Fishes a river from a flat boat or the bank, with a cast net, wicker traps and a weir of stakes. Barefoot, with a pole and a creel.", "A river is owned by the stretch, and the right to a weir is older than most titles. Millers and fishers have been at law since the first dam."),
        ["fisher/eel trapper"] = ("Sets long wicker traps in reeds and millponds and spears eels in the mud with a many-pronged fork. Carries the catch alive in a wet basket.", "Rents were paid in eels by the thousand. Nobody knows where the eels come from, and the trappers say they would rather not know."),
        ["fisher/shellfish gatherer"] = ("Walks the shore at low tide with a rake, a knife and a basket, for mussels, cockles and oysters. Skirts tucked up and bare feet in the mud.", "Poor people's work, done by women and children between the tides. The shell heaps behind a shore village are older than the village."),
        ["fisher/crab catcher"] = ("Sets baited pots of wicker among the rocks and hauls them by rope from a small boat. The catch goes to market alive, with bound claws.", "Pots are marked with the owner's knot, and to lift another's pot is the one theft a fishing village does not forgive."),
        ["fisher/shrimp catcher"] = ("Pushes a wide net on a frame through the shallows, wading to the waist or behind a horse. Boils the shrimp in a cauldron on the beach.", "Shoalfolk children take the push net out at the first ebb they can stand in. The catch is boiled on the sand and sold before it cools."),
        ["fisher/whaler"] = ("Hunts whales from an open boat with a harpoon on a long line, and cuts the blubber on the shore. Greasy leather, an iron lance and a hard face.", "Northmen divide a whale by law: so much to the harpooner, so much to the boat, so much to the shore it lands on. The shares are older than their kings."),
        ["fisher/sealer"] = ("Hunts seals on ice and skerries with a club, a harpoon and a knife. Dressed in sealskin, dragging the kill on a small sled.", "The Hoarkin ask the seal's leave at the breathing hole and give its first drink of fresh water back to the dead animal, so that it returns."),
        ["fisher/pearl diver"] = ("Dives without air to the oyster beds, with a stone weight on the foot, a nose clip and a net bag. Lean and deep-chested, with reddened eyes.", "A Shoalfolk diver counts a life in dives, not years. Deaf by thirty, most of them, and proud of it."),
        ["fisher/sponge diver"] = ("Dives naked from a small boat with a knife and a flat stone, and cuts sponges from the sea floor. The catch dries in strings on the mast.", "The divers go down holding a flat stone and come up when the lungs say so. A village counts its widows after every season."),
        ["fisher/coral diver"] = ("Brings up branches of red coral from deep rock, by diving or with a weighted wooden cross hung with nets and dragged from a boat.", "Red coral is hung on children against the evil eye. The divers do not wear it: they say the sea knows its own."),
        ["fisher/fish drier"] = ("Splits and guts fish and hangs them by the tail on wooden racks in the wind, or lays them salted on the rocks. Works with a broad knife, among gulls.", "Dried cod is the bread of the north and keeps for years. The Hoarkin dry fish through the light half of the year, to wake to in the dark half."),
        // hunter
        ["hunter/hunter"] = ("Hunts game with bow, spear and hounds. Dressed in green and brown wool and leather, with a horn and a long knife at the belt.", "In the lord's forest the same deed is sport for one man and a hanging for another. A hunter gives the first cut to whoever helped, even if only by keeping quiet."),
        ["hunter/trapper"] = ("Sets snares, pits and deadfalls for fur and meat along a line walked every few days. Carries a pack of pelts stretched on hoops.", "A trap line is property, handed from father to son, and to walk another's line is to ask for a fight. Northmen pay their dues to the south in pelts."),
        ["hunter/fowler"] = ("Catches wild birds with nets, limed twigs, decoys and a caller's whistle, in marsh and hedgerow. Carries cages and a pole of dead birds.", "Paid by the dozen for the lord's table and fined for the same birds on his own. The fowler's whistle is banned in some towns as a thief's signal."),
        ["hunter/falconer"] = ("Trains hawks and falcons to hunt and carries one hooded on a thick leather glove. Wears a pouch of meat, a lure on a cord and small bells.", "A falcon marks its owner's rank more surely than a ring: the law says which bird a king, a lord and a priest may fly. The falconer outranks the cook."),
        ["hunter/forager"] = ("Gathers what the wild land gives: nuts, berries, mushrooms, roots and herbs. A basket on the back, a digging stick and a sharp eye.", "Every village has one who knows where the morels come up and will not say. Elves forage without leaving a sign that they passed."),
        ["hunter/honey hunter"] = ("Climbs trees and cliffs to wild bees' nests on ropes of bark, with a smoking torch and a long knife. Comes down with combs in a bark pail.", "A bird leads the hunter to the nest and is owed its share of the comb. Those who cheat the bird are led to a snake the next time, the Sunlanders say."),
        ["hunter/tracker"] = ("Reads the ground for prints, droppings and broken twigs, and follows a beast or a person for days. Travels light and crouches often.", "Duskreaders track by the warmth a foot leaves on cold sand and can tell how long ago it passed. Courts hire them and do not ask how."),
        ["hunter/guide"] = ("Leads strangers through wild land by ways not on any map: the pass, the ford, the safe spring. A staff, a worn cloak and a coil of rope.", "A guide's word is law on the way, even over a lord. One who loses a traveller does not find work again."),
        ["hunter/scout"] = ("Goes ahead of an army or a caravan to see and not be seen. Lightly armed, in dull colours, on foot or on a small quick horse.", "Widegaze scouts are hired by both sides of the same war and keep to a rule: never report on the one who paid first."),
        ["hunter/ratcatcher"] = ("Clears houses, barns and ships of rats with terriers, ferrets, traps and poison. Carries a pole hung with dead rats as a sign.", "Catfolk hold the trade in every granary town, and are suspected of leaving a breeding pair behind to keep it."),
        ["hunter/monster hunter"] = ("Hunts the beasts that hunt people, for a bounty. Scarred, in mismatched armour, with a heavy spear, silvered blades, nets and flasks of oil.", "The guilds price a contract by the beast and by the widow's share. Few hunters grow old, and the old ones teach."),
        // forester
        ["forester/woodcutter"] = ("Fells and lops small timber and coppice with an axe and a billhook, and carries it out on the back. A poor man in a patched hood.", "The hero of half the tales and the poorest man in them. He has the right to dead wood, by hook or by crook, and no more."),
        ["forester/lumberjack"] = ("Fells great trees with a long axe and a two-man saw, and hauls the logs with oxen or floats them down a river. Broad-shouldered, in spiked boots.", "The crews winter in the forest and come down with the logs in spring, with a season's pay and a season's thirst."),
        ["forester/sawyer"] = ("Saws logs into planks over a pit, one man on top of the log and one below in the dust, with a long two-handed saw.", "Top sawyer and bottom sawyer: one has the skill and the air, the other the sawdust in his eyes. It is a saying for every unequal partnership."),
        ["forester/forest warden"] = ("The lord's officer in the wood: rides its bounds, marks the trees that may fall and fines those who cut or hunt unasked. A green coat, a horn, a bow and a badge.", "The most hated officer of any lord. Forest law takes a hand for a deer, and half the outlaws in the greenwood were made by a warden."),
        ["forester/grove warden"] = ("Keeps an old or holy wood where no axe may go. Walks it barefoot with a staff, knows every tree, and turns strangers back at its edge.", "Amberbloods keep the groves where their dead stand as trees. A warden knows each one by its living name."),
        ["forester/resin tapper"] = ("Cuts slanting notches in pine trunks and hangs small pots under them to catch the resin. Sticky hands, a scraping iron and a yoke of pails.", "Amberbloods will tap a pine and will not let it be bled dry: they know what it is to have resin for blood."),
        ["forester/tree shaper"] = ("Bends, binds and grafts living trees over many years until they grow into arches, bridges and halls. Works with cords, wedges and great patience.", "An Elf begins a hall that the grandchildren of its first guests will sit in. No other people has the years for the craft."),
        ["forester/firewood seller"] = ("Brings bundled faggots and split logs to town on a donkey or on the back, and cries them in the street.", "The price of faggots is the first thing a town council fixes in a hard winter, and the firewood seller the first to be accused of hoarding."),
        // miner
        ["miner/ore miner"] = ("Follows a vein underground with a pick, a hammer and iron wedges, by the light of a tallow lamp. A leather cap, a hooded tunic and a leather seat.", "Free miners answer to their own court and to no lord, in most lands. They leave a share of bread for whatever knocks in the dark, and do not whistle underground."),
        ["miner/prospector"] = ("Walks the hills looking for signs of ore: stained rock, heavy gravel, the plants that grow over metal. Carries a small pick, a pan and a bag of samples.", "Dwarves register a find at the gate of the hold before telling their own kin. A prospector's map is the one thing a Dwarf will lie about."),
        ["miner/gold washer"] = ("Stands in a cold stream and swirls gravel in a wide wooden pan or over a fleece, for the flecks of gold left behind.", "Sunlanders wash gold from the rivers in the dry season, and what a woman finds in her pan is hers alone."),
        ["miner/tin streamer"] = ("Digs the gravel of a valley floor and washes it in a channel of running water until the heavy black tin stone is left.", "The tinners have their own parliament and their own gaol. Their washings silt the harbours downstream, and the lawsuits are as old as the works."),
        ["miner/coal miner"] = ("Cuts coal from a low seam lying on one side, black from head to foot, and drags it out in a basket or a sled.", "Smiths wanted the coal and towns banned its smoke. The colliers live apart and marry among themselves, like the charcoal burners before them."),
        ["miner/gem miner"] = ("Digs narrow pits and sieves the gravel for rough stones, or chisels them from a rock face. Keeps the finds in a pouch tied inside the shirt.", "The pit owner searches the miners at the end of the day, and the miners have a hundred ways to swallow a stone."),
        ["miner/crystal miner"] = ("Climbs to clefts high in the mountains and levers clear crystals from their pockets with an iron bar. In a world with magic, also digs the crystals that hold it.", "The crystal hunters of the high peaks work alone and tell no one their clefts. A college of mages pays for mana crystal by the grain."),
        // quarryman
        ["quarryman/quarrier"] = ("Breaks blocks from a rock face with wedges, levers and sledgehammers in an open quarry. Grey with dust, in a leather apron.", "Quarries are where captives and convicts are sent. A free quarrier wears his own hammer at his belt on feast days, to show which he is."),
        ["quarryman/stonecutter"] = ("Squares rough blocks to size with a mallet, chisels and a stone axe, in a shed at the quarry or at the building site.", "Paid by the block, and each block carries his mark so that a bad one can be traced. Dwarves read those marks like signatures."),
        ["quarryman/slate splitter"] = ("Sits with a block of slate against the knee and splits it into thin roofing sheets with a broad chisel and a mallet.", "A good splitter gets sixteen sheets from a block and names the sizes after ranks of ladies: queens, duchesses, countesses."),
        ["quarryman/millstone cutter"] = ("Cuts round millstones from hard gritty rock and dresses their faces with furrows. The finished stones stand on edge, as tall as a person.", "A stone that cracks on the way down the hill is left where it lies. The hillsides under the old quarries are strewn with them."),
        ["quarryman/sand digger"] = ("Digs sand from a pit or a river bank with a shovel and carts it to the builders and the glassmakers.", "A glass town will pay for one pit's sand and refuse the next pit's. The Brinefolk say they can taste the difference."),
        ["quarryman/gravel digger"] = ("Digs and sieves gravel from river terraces for roads and yards, and loads it into carts with a wide shovel.", "The Old Realms laid their roads on gravel an arm deep. What a digger does now is mostly patch them."),
        ["quarryman/clay digger"] = ("Cuts wet clay from a pit with a narrow spade and leaves it in heaps to weather for the potter and the brickmaker.", "The pits fill with water and become the village ponds. A potter's family and a digger's family are usually the same family."),
        // salter
        ["salter/salt boiler"] = ("Boils brine in wide lead or iron pans over a fire that never goes out, and rakes the white crust to the side. Stripped to the waist in the steam.", "A salt town burns a forest every generation. The boilers are paid in salt, and the word for a wage comes from it."),
        ["salter/pan master"] = ("Owns or runs a salt works and judges the moment when the pan is ready to draw. Tastes the brine, and keeps the tally of every basket.", "The right to a pan is inherited, sold and mortgaged like a house. In a salt town the pan masters are the council."),
        ["salter/salt raker"] = ("Rakes sea salt into white heaps on the clay floors of shallow pans by the shore, under a hot sun. A long wooden rake, a wide hat and bare feet.", "The Brinefolk rake the flats of their dried sea and hold them in trust until the water comes back. They weep salt, and count that as rent."),
        ["salter/rock-salt miner"] = ("Cuts blocks of grey and pink salt from galleries deep underground and carries them up on the back. The walls glitter in the lamplight.", "The miners carve chapels, altars and saints out of the salt, deep underground, and are buried from them."),
        ["salter/brine worker"] = ("Draws brine from a well or a spring by bucket and windlass and carries it to the boiling houses in wooden pipes or pails.", "The well belongs to the town and the brine is shared out by the bucket, by a tally older than the walls."),
        ["salter/soda burner"] = ("Burns seaweed or salt-marsh plants in a pit to a grey cake of soda, for the glassmakers and the soap boilers. Works in bitter smoke on a bare shore.", "The glass towns buy all the soda a shore can burn. The burners are left with the smoke and a coast without a blade of grass."),
        // miller
        ["miller/water miller"] = ("Keeps a mill on a stream, where a great wooden wheel turns the stones. White with flour, with a sack on the shoulder and a toll dish in the hand.", "Tenants must grind at the lord's mill and pay the miller his toll, and no one has ever believed the toll dish was honest. The mill pond is where the village drowns its secrets."),
        ["miller/windmill keeper"] = ("Keeps a wooden mill on a hill, turns it to face the wind by its tail pole and sets the cloth on its four sails.", "A miller sets the sails to a cross for a death and to a slant for a wedding, and the country reads the news from the hill."),
        ["miller/horse-mill keeper"] = ("Grinds where there is no stream and no steady wind: a horse or a donkey walks a circle and turns the stones.", "Slow and dear, and the only mill a town can keep turning inside its walls in a siege."),
        ["miller/oil presser"] = ("Crushes olives, nuts or seed under a rolling stone and squeezes the mash in a press of beams and screws. The oil runs into jars; everything shines with it.", "The last pressing lights the lamps and the first goes to the temple. The press house is the one warm place in the village in the cold months, and everyone finds a reason to be there."),
        ["miller/fuller"] = ("Runs a mill whose wheel lifts heavy wooden hammers that pound wet cloth in troughs of water and fuller's earth.", "The hammers thump day and night and can be heard a valley away. The first machines to put hands out of work, and the first to be broken for it."),
        ["miller/sawyer"] = ("Runs a mill whose wheel drives a saw blade up and down through a log, and stacks the planks to dry.", "The pit sawyers burned the first sawmills. The mills came back, and the sawyers' sons work in them."),
        // baker
        ["baker/baker"] = ("Kneads dough in a wooden trough before dawn and bakes loaves in a brick oven, drawing them out on a long wooden peel. Floured arms and a white cap.", "A short loaf earns the baker a ride through the streets with it round his neck. So bakers give thirteen to the dozen, to be safe."),
        ["baker/keeper of the common oven"] = ("Fires the village oven and bakes the dough each household brings, marked with its own sign, for a share of the loaves.", "Every household's loaf carries its own mark, and the keeper knows by the dough who is doing well and who is stretching the flour."),
        ["baker/pastry cook"] = ("Makes fine things of flour, butter, honey and spice for rich tables: tarts, wafers and gilded cakes. Works with moulds, irons and a light hand.", "At a feast the pastry is the lord's boast: castles of sugar, pies with live birds. Halflings hold that the pastry cook outranks the knight."),
        ["baker/pie maker"] = ("Bakes meat, fish and fruit in thick crusts and sells the pies hot from a tray in the street.", "Nobody asks a pie maker what is in the pie. The trade is fined for it every market day and thrives anyway."),
        ["baker/cook"] = ("Cooks for sale: stews in great pots, roasts on a spit, and sells by the bowl and the slice. A stained apron, a ladle and a red face.", "Halflings rank a cook with a priest. Among the Orcs, who can eat anything, the cook is the one who makes it worth doing."),
        ["baker/cookshop keeper"] = ("Keeps a shop open to the street with a counter and a fire, where those without a kitchen buy a hot meal or bring their own meat to be roasted.", "Half a town has no hearth of its own and eats from the cookshop. It never closes, and so it hears everything."),
        // brewer
        ["brewer/brewer"] = ("Mashes malt in hot water in a great tun, boils the wort with hops or herbs and ferments it in open vats. Works in steam, with a long wooden paddle.", "Dwarves brew strong and keep the yeast of a hold alive for centuries: a brewer who loses it is remembered by name. Monks brew the best ale and say it is for the guests."),
        ["brewer/alewife"] = ("A woman who brews ale in her own kitchen and sells it at the door, with a bush on a pole outside when a new brew is ready.", "The ale taster calls unannounced and fines her either way: for weak ale, or for a short measure. The fine is a licence under another name."),
        ["brewer/maltster"] = ("Soaks barley, spreads it on a floor to sprout and dries it over a kiln, turning it with a wooden shovel.", "A malt kiln burns down oftener than any other building in a town. The maltster lives beside it and sleeps lightly."),
        ["brewer/wine maker"] = ("Treads grapes in a vat, presses the skins and keeps the wine in barrels in a cool cellar. Legs stained purple at the vintage.", "Elves lay down a vintage for a guest who is not yet born. Everyone else drinks the wine within the year, before it turns."),
        ["brewer/cider maker"] = ("Crushes apples in a stone trough under a rolling wheel and presses the pulp between layers of straw.", "Halflings pay a harvest hand part of the wage in cider and take the quality of both seriously."),
        ["brewer/mead maker"] = ("Ferments honey and water in crocks, plain or with herbs and fruit. A golden drink for feasts and halls.", "The drink of the Northmen's halls. An oath sworn over the mead horn binds as hard as one sworn on iron."),
        ["brewer/distiller"] = ("Heats wine or mash in a copper still and catches the strong spirit that drips from its beak. Half brewer, half alchemist.", "The alchemists called it the water of life and sold it as medicine. The Gnomes made the still that made it a drink."),
        // butcher
        ["butcher/butcher"] = ("Cuts up carcasses on a heavy block and sells meat from an open stall hung with joints. A cleaver, a knife steel and a bloody apron.", "Butchers are rich, armed with their tools and quick to riot, and no council crosses their guild lightly. They may not serve on a jury in a trial for blood."),
        ["butcher/slaughterer"] = ("Kills cattle, sheep and pigs with a poleaxe and a knife, bleeds them and skins them. Works in a yard by running water.", "Kept outside the walls and downstream by law. In some faiths the slaughterer must be a priest, and in others he may never enter the temple."),
        ["butcher/poulterer"] = ("Sells hens, geese, ducks and game birds, alive in wicker cages or plucked and hung by the feet.", "The goose girl and the poulterer's wife are the gossips of every tale. Feathers go to the fletcher and the bedmaker, and nothing is wasted."),
        ["butcher/tripe seller"] = ("Washes and boils the stomachs, feet and heads the butcher cannot sell, and sells them cheap and hot from a tub.", "The food of the poor and of the morning after. Orcs say a people that will not eat tripe has never been hungry."),
        ["butcher/fishmonger"] = ("Sells fish from a wet stone slab or a barrel: fresh from the boats, or salted, smoked and dried from far away.", "On fast days the fishmonger is the richest man in the market. The fishwives' tongue is a byword in every port."),
        ["butcher/fish salter"] = ("Guts fish and packs them in barrels between layers of salt, or hangs them in a smokehouse. Hands cracked by brine.", "A barrel of herring is sealed with the town's brand, and a false brand costs the salter a hand."),
        ["butcher/pickler"] = ("Keeps meat, fish and greens in brine, vinegar and spice, in rows of crocks and casks.", "Halfling cellars got them through the Ashen Years, and the pickler is honoured for it at every harvest feast."),
        ["butcher/renderer"] = ("Boils fat, bones and scraps in great cauldrons for tallow, lard, glue and oil. A foul trade at the edge of town.", "The trade nobody will live beside and no one can do without. Hoarkin render blubber on the ice, where the smell offends no one but the bears."),
        ["butcher/tallow chandler"] = ("Dips wicks again and again into hot tallow until they are candles, and hangs them in rows on a rack to harden.", "Tallow for the house, wax for the temple. The two chandlers' guilds have been at law for longer than either can prove."),
        ["butcher/soap boiler"] = ("Boils fat with lye from wood ash in an iron kettle, stirs for hours and cuts the cooled soap into bars.", "Soap is a town luxury; the country uses lye and sand. The Stillfaces, who speak by scent, will not let a scented soap into the house."),
        // charcoalBurner
        ["charcoalBurner/collier"] = ("Stacks wood into a round mound, covers it with turf and lets it smoulder for days, watching day and night from a hut beside it. Black with soot.", "Sits on a one-legged stool, so that he falls and wakes if he dozes while the clamp burns. Outlaws and lost children are both said to be safe at a collier's fire."),
        ["charcoalBurner/tar burner"] = ("Burns resinous pine roots in a covered pit on a slope and catches the black tar that runs out at the bottom in barrels.", "Northmen tar their ships, their roofs and their ropes, and a district pays its tax in barrels. The pits can be smelt from the sea."),
        ["charcoalBurner/pitch boiler"] = ("Boils tar down in an iron cauldron until it is thick black pitch, for ships, barrels and torches.", "A pitch kettle that catches takes the yard with it. Shipwrights keep the boilers at the far end of the beach."),
        ["charcoalBurner/ash burner"] = ("Burns hardwood to ash, washes the ash with water and boils the lye dry for potash, in iron pots in the forest.", "It takes a great tree to make a small pot of potash. The glassmakers and the soap boilers pay, and the forest does not come back."),
        ["charcoalBurner/varnish maker"] = ("Melts resins and amber with oil in a small pot over a careful fire, and sells the clear varnish to painters and joiners.", "Amberbloods make the best varnish and will not say what is in it. The other peoples have a guess, and do not ask."),
        ["charcoalBurner/lime burner"] = ("Burns limestone in a stone kiln on a hillside and draws out white quicklime for mortar. Wrapped in cloth against the burning dust.", "The kiln's fumes kill a sleeper beside it, and tramps who lie down by a warm kiln are found there in the morning."),
        // smelter
        ["smelter/bloomery man"] = ("Smelts iron in a clay furnace the height of a person, working the bellows for hours, and draws out a glowing spongy lump to hammer.", "Sunlanders were the first to smelt iron. The furnace is built like a woman giving birth, and the smelters keep apart from their wives while it burns."),
        ["smelter/iron smelter"] = ("Roasts and smelts iron ore with charcoal and sells the metal in bars. A leather apron, long tongs and arms scarred by sparks.", "The works follow the wood. A valley is smelted bare in a generation, and the smelters move on and leave a name with hammer in it."),
        ["smelter/furnace master"] = ("Runs a great furnace blown by water-driven bellows and commands its crew. Judges the heat by the colour of the flame, and taps the molten metal.", "Reads the flame through a hole the size of a coin and is paid more than the lord's steward. Hearthbloods stand closer to the tap than anyone else can."),
        ["smelter/copper smelter"] = ("Roasts green and grey copper ore on open heaps and smelts it to red metal. The smoke kills the trees around the works.", "The ground round the roasting heaps stays bare for a lifetime. The smelters are short-lived and well paid, and know the bargain."),
        ["smelter/silver refiner"] = ("Melts silver-bearing lead on a hearth of bone ash and blows air across it until a bright button of silver is left.", "Works under the eye of the ruler's assayer. What is left in the hearth belongs to the refiner, and refiners have grown rich on sweepings."),
        ["smelter/steel maker"] = ("Bakes iron with charcoal in sealed clay pots until it becomes steel, by a recipe passed from parent to child.", "The Rainkeepers make the watered steel that every swordsmith wants, and are born into the work. The recipe has never been written down."),
        ["smelter/bronze founder"] = ("Melts copper and tin together in a crucible and pours the bronze into ingots, at the works where the ore is smelted.", "Bronze was the metal of the Dawn. The founders say iron is a fashion, and are still waiting."),
        // tanner
        ["tanner/tanner"] = ("Soaks hides in pits of lime and oak bark for months and scrapes them over a beam with a two-handled knife. Stained brown, and smelt from afar.", "Banished downstream and downwind. Tanners marry tanners, and the saying is that nothing gets the smell out but a second fortune."),
        ["tanner/tawyer"] = ("Makes soft white leather with alum, salt and egg yolk instead of bark, for gloves and fine goods.", "White leather for the gloves of the rich. The tawyers hold themselves above the tanners and are kept to the same end of town."),
        ["tanner/currier"] = ("Finishes tanned leather: shaves it even, works in oil and tallow and stretches it until it is supple and coloured.", "A hide is no use until the currier has had it, and the shoemakers hate paying for that. The two guilds share a street and not a word."),
        ["tanner/skinner"] = ("Flays carcasses and trades in raw hides and pelts, salted and bundled.", "The skinner takes the dead horse and the dog nobody claims. In some towns he is also the hangman's man."),
        ["tanner/furrier"] = ("Dresses pelts with the hair on and matches them into linings and trims. A rich trade with soft hands, among hanging furs.", "The law says who may wear which fur, and the furrier knows who breaks it. As rich as a mercer, and never quite as welcome."),
        ["tanner/parchment maker"] = ("Stretches limed calf and sheep skins on a wooden frame and scrapes them thin with a moon-shaped knife, until they are smooth white sheets.", "A book takes a flock. The parchment maker counts a library in sheep, and sells the best skins to the Lanternkin for their contracts."),
        // weaver
        ["weaver/spinner"] = ("Spins wool or flax to thread with a distaff and a drop spindle, or at a wheel. Mostly a woman, and spinning at every idle moment.", "Every woman spins, and the law calls an unmarried one by the name of the work. It takes eight spinners to keep one weaver at the loom."),
        ["weaver/weaver"] = ("Sits at a wooden loom, throws the shuttle through the warp and beats the cloth tight. A cramped workshop with a window for light.", "Weavers think while they work, and think the same things: the weavers' quarter is where every heresy and every rising begins."),
        ["weaver/linen weaver"] = ("Weaves fine linen from flax thread in a damp cellar, where the thread does not snap, and bleaches the cloth on the grass.", "Works in a damp cellar and coughs from it. The poorest of the weavers, and the proverb makes him the least honest."),
        ["weaver/silk weaver"] = ("Weaves patterned silk on a tall loom, with a helper perched above to pull the pattern cords. The richest cloth, for court and temple.", "A master's pattern is the family's fortune. A weaver who carries it out of the town has put a price on his own head."),
        ["weaver/fuller"] = ("Treads new woollen cloth in a trough of water, stale urine and fuller's earth to clean and thicken it. Bare legs and a strong smell.", "The fullers walk the cloth and sing to keep time. No one sits near them in the tavern, and they have stopped minding."),
        ["weaver/dyer"] = ("Boils cloth and yarn in vats of colour and lifts them out on poles, with arms stained to the elbow.", "Known by the hands. The dyer of red and the dyer of blue are separate guilds and may not touch each other's vats. Boughwalkers dye in a colour that no one else can see."),
        ["weaver/shearman"] = ("Raises the nap of finished cloth with teasels and crops it smooth with shears as long as an arm.", "The last hand on the cloth and the one that can ruin it. A shearman's shears are his own and are buried with him."),
        ["weaver/felt maker"] = ("Lays wet wool in layers and rolls, beats and treads it into felt, for hats, boots, rugs and tents.", "The Grass riders live under felt, walk on it and are buried in it. The felt for a new tent is rolled by the whole camp."),
        ["weaver/carpet weaver"] = ("Knots coloured wool onto an upright loom, row by row, from a pattern held in the head, and trims the pile with shears.", "A carpet takes a year and tells who made it: every people ties its own knot. The makers leave one fault in on purpose, since only a god's work is whole."),
        ["weaver/rope maker"] = ("Walks backwards down a long ropewalk paying out hemp from a bundle at the waist, while a wheel twists the strands into rope.", "The ropewalk is the longest building in a port. The hangman buys there, and the rope maker does not ask which coil."),
        ["weaver/net maker"] = ("Knots twine into fishing and fowling nets with a flat wooden needle and a mesh gauge, and mends torn ones by the harbour.", "Old sailors and fishers' widows mend nets on the quay. The Shoalfolk tie a knot into each net that names the family."),
        // smith
        ["smith/blacksmith"] = ("Heats iron in a charcoal forge and hammers it on an anvil. A leather apron, bare forearms, tongs and a hammer, in a dark smithy lit by the fire.", "Every village needs one and half fear theirs. The smith pulls teeth, binds oaths on the anvil and, in the far north, marries couples over it."),
        ["smith/farrier"] = ("Shoes horses: pares the hoof, fits the hot shoe in a hiss of smoke and nails it on. Also doctors the horse.", "A horseshoe over the door keeps luck in, points up. The farrier is the horse's physician and often the village's too."),
        ["smith/toolsmith"] = ("Forges edged tools: axes, scythes, chisels and spades, with a strip of steel welded into the edge.", "Dwarven tools carry a maker's mark and a warranty of a lifetime, and the Dwarves mean a Dwarf's lifetime."),
        ["smith/nailer"] = ("Makes nails all day at a small forge: heats a rod, points it, cuts it and heads it with a few blows. Poor piece-work.", "The poorest of those who work iron: whole families at one small forge, paid by the thousand. A nailer's child can make a nail before it can read."),
        ["smith/cutler"] = ("Makes knives, shears and razors, grinds them on a wheel and fits the handles of horn, bone and wood.", "A knife carries its town's mark, and a town will go to war over a forged one. Everyone eats with their own knife and is judged by it."),
        ["smith/locksmith"] = ("Files locks, keys, hinges and iron-bound strongboxes at a bench, with small tools and a vice.", "Sworn never to make a key from a wax print or for a stranger. The oath is taken before the whole guild, and broken in private."),
        ["smith/weaponsmith"] = ("Forges swords, spearheads and axes, and hardens them in oil or water. The blades are tested and marked with the maker's stamp.", "A sword has a name and a lineage, and its smith is remembered with it. Some smiths will not sell to a man they dislike the look of."),
        ["smith/armourer"] = ("Hammers plates of steel over stakes and rounded anvils into helmets and harness, and rivets mail ring by ring.", "Dwarves fit a harness to the man like a tailor and keep his measures on file, with his debts."),
        ["smith/sword polisher"] = ("Grinds and polishes finished blades on stones of ever finer grit until the steel shines, and fits hilt and scabbard.", "The polisher sees what the smith hid: every flaw comes up under the stone. The guild is larger than the swordsmiths', and prouder."),
        ["smith/bronze founder"] = ("Casts bronze and brass in moulds of clay and wax in a town workshop: pots, buckles, statues and fittings.", "Sunlanders cast the heads of their kings in bronze, and the founders are a caste that serves the palace alone."),
        ["smith/bell caster"] = ("Casts great bells in a pit dug beside the temple that ordered them, and tunes each by chipping metal from its rim.", "A bell is cast at night, beside the tower it is for, with the whole town watching. People throw in silver for the tone, and the caster lets them."),
        ["smith/forge hand"] = ("Works the bellows, feeds the fire and swings the sledgehammer to the smith's tap. Sweating, in a scorched apron.", "Hearthbloods work the fire bare-armed where others need tongs and leather, and Dwarven holds hire them by the company."),
        // carpenter
        ["carpenter/carpenter"] = ("Hews beams with an axe and an adze and joins them with pegs into house frames, roofs and barns. Carries a saw, an auger and a chalk line.", "A house frame is cut on the ground, every joint numbered, and raised in a day by the whole village. A green bough is nailed to the ridge, and the owner pays in ale."),
        ["carpenter/joiner"] = ("Makes fine fitted work at a bench with planes and chisels: doors, panelling, tables and benches, without a nail.", "The carpenters say a joiner is a carpenter afraid of heights. The joiners say a carpenter is a joiner who cannot measure."),
        ["carpenter/wheelwright"] = ("Builds wheels: a turned hub, oak spokes, curved rim pieces, and an iron tyre shrunk on hot.", "A wheel is the hardest thing a village makes. Tyring day needs the smith, a fire in the yard and every hand that can hold a bucket."),
        ["carpenter/cartwright"] = ("Builds carts and wagons: frame, axle, shafts and boards, with the wheelwright's wheels.", "Every district builds its own cart, and a stranger's home can be told from his wagon before he speaks."),
        ["carpenter/cooper"] = ("Shapes staves, bends them over a fire and binds them with hoops into barrels, tubs and buckets that hold water.", "A barrel is the measure of trade, and the cooper's mark is the warrant that it holds what it should. An apprentice is rolled in his first barrel."),
        ["carpenter/turner"] = ("Turns bowls, cups, spindles and chair legs on a lathe worked by a foot treadle and a springy pole.", "Turners work in the woods where the timber stands, through the summer, and come to the fair with a cartload of bowls."),
        ["carpenter/chest maker"] = ("Makes chests and coffers of boards, bound with iron and often carved or painted: the main furniture of every house.", "A bride brings her chest and a dead man leaves his. Whoever holds the key to the chest holds the house."),
        ["carpenter/bowyer"] = ("Shapes bow staves of yew, ash or elm with a drawknife, or glues horn, wood and sinew into short recurved bows.", "Elves season a stave for longer than a human bowyer lives. The Grass riders glue horn and sinew, and take a year over a bow they will not sell."),
        ["carpenter/fletcher"] = ("Makes arrows: straightens the shafts, glues and binds on goose feathers, and fits the iron heads.", "The king takes six feathers from every goose in time of war. A fletcher counts the peace in geese."),
        ["carpenter/sled maker"] = ("Builds sleds and sledges of bent wood lashed with hide, without nails, for snow and ice.", "The Hoarkin build without iron, because iron snaps in the cold, and lash with hide so that the sled gives on rough ice."),
        ["carpenter/woodcarver"] = ("Carves figures, leaves and beasts into beams, doors, ship prows and furniture, with gouges and a mallet.", "Amberbloods carve only wood that fell by itself. The Northmen put a beast's head on the prow and take it off in sight of land, so as not to frighten the spirits there."),
        // shipwright
        ["shipwright/shipwright"] = ("Builds seagoing ships on a slipway by eye, without drawings: keel, ribs and planking, with an adze, an axe and an auger.", "Built by eye and by a rule of thumb passed down in the family. Northmen name the ship at the keel-laying, and once put more than a name under the keel."),
        ["shipwright/boatbuilder"] = ("Builds small craft on the beach: rowing boats, fishing boats and skiffs, of overlapping planks riveted together.", "Every shore has its own boat, shaped by its own surf. The Shoalfolk are born in one and build their first before they marry."),
        ["shipwright/caulker"] = ("Drives tarred hemp into the seams of a hull with a caulking iron and a mallet, and seals them with hot pitch.", "The sound of the mallets is how a port knows its yard is in work. The space between the planks is called the devil, and the caulker pays him."),
        ["shipwright/hull mender"] = ("Repairs ships in harbour: patches sprung planks, scrapes weed and shell from the bottom, and where the mender can dive, works under the water.", "Shoalfolk menders work under water on one breath and are hired in every harbour, though no land law reaches them and no harbour master likes it."),
        ["shipwright/sail maker"] = ("Sews strips of heavy canvas into sails in a wide loft, with a three-sided needle and a leather palm, and ropes their edges.", "A sail loft is the largest dry floor in a port, so it is also where the town dances. Winds, where they can be bought, are sewn into a hem."),
        ["shipwright/barge builder"] = ("Builds flat-bottomed barges and lighters for rivers and canals, wide and shallow, to carry grain, stone and timber.", "The Halflings' river barges are homes as much as boats, and a builder is paid part of the price in dinners aboard."),
        // mason
        ["mason/stonemason"] = ("Cuts stone to a line with a mallet and chisels and lays it true with plumb line, square and level. Dusty, in a leather apron, with his mark on every block.", "Masons travel to where the great works are, lodge together and know each other by signs. What the lodge teaches is geometry, and what it keeps is silence."),
        ["mason/bricklayer"] = ("Lays brick in courses with a trowel and mortar along a stretched line, on a scaffold of poles.", "The masons call brick the poor man's stone. The bricklayers answer that half the cities of the Old Realms are brick and still standing."),
        ["mason/builder"] = ("Takes on a whole building for a price and brings the crew: reads the ground, sets out the walls with pegs and cord, and oversees the work.", "A builder who has never had a wall fall has not built enough, the saying goes. The contract names a penalty for each week late, and each week is late."),
        ["mason/plasterer"] = ("Coats walls and ceilings with lime plaster from a board, with a trowel and a float, and whitewashes them.", "A fresh wall waits for the painter. A plasterer who puts a hand to it himself is fined by the painters' guild."),
        ["mason/tiler"] = ("Lays clay tiles on roofs and floors, pegging or bedding each one. Works on the roof with a tile hammer.", "After a town burns, the council orders tile for every roof, and the tilers are rich until the order is forgotten."),
        ["mason/roofer"] = ("Covers roofs with slate, wooden shingles or lead sheet. Works high on the laths with a pick-hammer and a pouch of nails.", "Roofers drink more than other builders, by repute, and fall less than the repute would suggest."),
        ["mason/thatcher"] = ("Lays bundles of reed or straw on a roof, pins them with hazel rods and combs them smooth with a toothed rake.", "Each thatcher finishes the ridge with a knot or a straw beast of his own, and a village can name the man from the roof."),
        ["mason/steeplejack"] = ("Climbs towers and spires on ropes and ladders to mend what no scaffold reaches. Light, sure-footed and without fear of height.", "Boughwalkers and Catfolk hold the trade in most cities. They are paid by the height, and the spire's weathercock is theirs to set."),
        ["mason/well digger"] = ("Digs a round shaft down to water and lines it with stone as it goes, hauled up and down in a bucket.", "Paid on water, not on depth. A dry shaft is the digger's loss, so diggers and dowsers work in pairs and blame each other."),
        ["mason/bridge builder"] = ("Builds bridges: drives piles in the river bed, raises piers, and turns stone arches over timber frames.", "The first to cross a new bridge belongs to the devil, the tale says, so a dog or a cock is sent over. Building one is a pious work that wipes out sins."),
        ["mason/engineer"] = ("Plans great works with compass, rule and model: walls, canals, harbours and aqueducts. A master in a long gown, with drawings and a measuring rod.", "Dwarven engineers sign a wall and answer for it for a hundred years. The Canal folk examine theirs before they let them touch a dike."),
        // potter
        ["potter/potter"] = ("Throws pots on a wheel turned by the foot, with wet hands. Rows of grey pots dry on boards before they go to the kiln.", "Potters leave more behind than kings do. In many faiths the first people were thrown on a wheel, and the potter says so when the price is questioned."),
        ["potter/brickmaker"] = ("Presses clay into wooden moulds, turns the bricks out in rows to dry and fires them in a great stacked clamp.", "A season's work, from the last frost to the first. The clamp burns for weeks, and its smoke marks the edge of every growing town."),
        ["potter/tile maker"] = ("Shapes roof and floor tiles in moulds or over the thigh, and fires them in a kiln. Floor tiles are stamped with patterns.", "The tile works belong to the temple or the lord more often than to the maker. A paw print in a tile is left in, for luck."),
        ["potter/kiln master"] = ("Stacks the kiln, feeds the fire for days and judges the heat by its colour through a spy hole. One mistake spoils the whole load.", "The kiln is opened at dawn with the whole pottery standing by. A god of the kiln has an altar on it, and gets the first pot or the blame."),
        ["potter/maker of fine ware"] = ("Makes thin, glazed and painted ware for rich tables, white-bodied or lustred, by a recipe that is the town's secret.", "The Canal folk kept the white ware to themselves for centuries. Courts elsewhere locked up alchemists until they found the recipe."),
        // glassmaker
        ["glassmaker/glassblower"] = ("Gathers molten glass on the end of an iron pipe, blows it into a bubble and shapes it with tongs, at the mouth of a roaring furnace.", "A glass town forbids its masters to leave and hunts those who do. In return they may marry into the nobility, and their furnaces never go out."),
        ["glassmaker/glazier"] = ("Cuts panes of coloured and clear glass and sets them in strips of lead to make windows.", "Coloured windows are the books of those who cannot read. The glazier signs with a small figure of himself in a corner, kneeling."),
        ["glassmaker/bead maker"] = ("Winds threads of molten glass round an iron rod over a lamp flame to make beads, in every colour.", "Beads are the coin of the long trade: a string buys ivory, gold or a guide where no one takes silver."),
        ["glassmaker/mirror maker"] = ("Backs flat or blown glass with tin and quicksilver, or polishes a disc of bronze, to make a mirror.", "The quicksilver takes the maker's teeth, then his wits. A mirror is covered in a house of mourning, and a mage will pay for one that was never looked into."),
        ["glassmaker/lens grinder"] = ("Grinds discs of glass or rock crystal against a curved dish with sand and water into reading stones and spectacle lenses.", "Gnomes ground the first spectacles and gave scholars twenty more years of reading. The scholars have not agreed whether to thank them."),
        ["glassmaker/vial blower"] = ("Blows small thin vessels at a lamp: vials, flasks and tubes for apothecaries, alchemists and mages. Fine work for steady breath.", "Lanternkin blow the vials that hold their own blood for a contract: it glows as long as the signer lives."),
        // leatherworker
        ["leatherworker/shoemaker"] = ("Cuts and sews new shoes and boots at a low bench in an open stall, with an awl, waxed thread and wooden lasts.", "The shoemaker thinks while he sews and talks while he fits, and every rising has a shoemaker in it. His own children go barefoot, by the proverb."),
        ["leatherworker/cobbler"] = ("Mends old shoes and remakes them for resale: patches, new soles and heels. Poorer than the shoemaker, with a bench in the street.", "The guilds have fought for centuries over how much new leather a cobbler may put in an old shoe. The cobbler is told to stick to his last, and does not."),
        ["leatherworker/saddler"] = ("Builds saddles over a wooden tree, padded and covered with leather, tooled and studded for those who can pay.", "A Grass rider is measured for a saddle once and rides it for life, and is buried on it."),
        ["leatherworker/harness maker"] = ("Cuts and stitches straps, collars, bridles and traces for draught and riding animals, and fits the buckles.", "A broken trace stops a harvest. The harness maker's lamp burns latest in the weeks before it."),
        ["leatherworker/girdler"] = ("Makes belts and girdles of leather and cloth, set with metal mounts, studs and buckles.", "A belt shows rank by its mounts, and the law says who may wear silver ones. A woman's keys hang from it, and a man's knife."),
        ["leatherworker/glover"] = ("Cuts gloves from soft thin leather with shears and sews them with tiny stitches, plain, embroidered or perfumed.", "A glove thrown down is a challenge, a glove given is a pledge, and a glove sent is a summons. Glovers scent them, and poisoners have learnt from glovers."),
        ["leatherworker/purse maker"] = ("Makes purses, pouches and bags that hang from the belt, of leather and cloth with drawstrings and clasps.", "The purse maker and the cutpurse know each other's work well. The strongest strings are sold with a wink."),
        ["leatherworker/scabbard maker"] = ("Makes sheaths for swords and knives: thin wood covered with leather, with a metal tip and mouth.", "The sword gets the name, and the scabbard gets the rain. A blade drawn from another man's scabbard is bad luck."),
        ["leatherworker/bookbinder"] = ("Covers the wooden boards of a book in leather and decorates it with stamps, tooling, bosses and clasps.", "A book is bound to outlast its owner and chained to outlast the thief. The clasp matters: parchment swells if it is not held shut."),
        // tailor
        ["tailor/tailor"] = ("Measures with a strip of parchment, cuts the cloth with great shears and sews sitting cross-legged on the table. A needle, a thimble and chalk.", "Nine tailors make a man, the insult goes. But the tailor knows every measure, every debt and every thickening waist in town."),
        ["tailor/seamstress"] = ("A woman who sews linen: shirts, shifts, sheets and caps, with fine even stitches, at home or in a workroom.", "Paid by the piece, and poorly. A girl's sampler shows her stitches to a mistress, and a seamstress's eyes last twenty years."),
        ["tailor/robe maker"] = ("Makes the long gowns of office and ceremony for priests, judges, scholars and mages, in rich cloth with wide sleeves.", "The cut and colour of a gown are law: a judge, a doctor and a mage may each be known at a hundred paces, and may not dress otherwise."),
        ["tailor/hosier"] = ("Cuts and sews close-fitting hose from cloth cut on the slant, or knits stockings.", "Parti-coloured hose in a lord's colours mark his men. The preachers call tight hose a sin, and the hosiers thank them for the custom."),
        ["tailor/hatter"] = ("Shapes felt over wooden blocks with steam into hats, and trims them with bands, brooches and feathers.", "A hat is doffed, and to whom is the whole of manners. Hatters go strange from the fumes of the felt, and it is said without malice."),
        ["tailor/embroiderer"] = ("Works pictures and patterns in silk and gold thread on cloth stretched in a frame, for vestments, banners and court dress.", "Vestments worth more than the church they hang in. The gold thread is weighed out to the embroiderer and weighed back."),
        ["tailor/garment furrier"] = ("Lines and trims clothes with fur: sews small pelts into a lining and fits it to gown, hood and cloak.", "A lining can be worth more than the gown and is unpicked to be left in a will. The belly fur of the squirrel is counted by the thousand."),
        ["tailor/old-clothes dealer"] = ("Buys worn clothes, mends and turns them, and sells them again from a stall hung thick with garments.", "Most people never wear a new coat. In a plague year the dealers are rich, and are blamed for the next street that falls sick."),
        // jeweller
        ["jeweller/goldsmith"] = ("Works gold at a bench by a small furnace: casts, hammers, solders and sets stones, for rings, chains and cups. A fine scale and a strongbox.", "The goldsmith keeps other people's plate and lends against it, and so became the first banker. The street of the goldsmiths is the best guarded in a city."),
        ["jeweller/silversmith"] = ("Raises cups, bowls and plate from sheets of silver with hammers over stakes, and chases them with patterns.", "A household's plate is its savings: melted in a bad year and made again in a good one. The silversmith has seen the same cups three times."),
        ["jeweller/gem cutter"] = ("Cuts and polishes facets on gems against a turning wheel dressed with grit, with the stone glued to a stick.", "One wrong stroke halves the price. Dwarves read a rough stone's flaws at a glance and will not cut one in a hurry for any king."),
        ["jeweller/lapidary"] = ("Knows, sorts, shapes and deals in stones: rounds and polishes them, carves seals and cameos, and tells true from false.", "The books of stones give each a virtue: amethyst against drink, sapphire against poison. The lapidary sells the virtue with the stone and does not vouch for it."),
        ["jeweller/engraver"] = ("Cuts lines into metal with a sharp steel point: letters, arms and ornament on plate, seals and dies. Works with a lens.", "The one who cuts the ruler's seal can forge the ruler's word. An old seal is broken before witnesses, and the engraver is watched."),
        ["jeweller/enameller"] = ("Fills cells in metal with powdered coloured glass and fires it until it melts into bright enamel.", "Colours that do not fade in a thousand years. The recipes are kept in the family, and a daughter's husband is chosen for his hands."),
        ["jeweller/moneyer"] = ("Strikes coin for the ruler: sets a blank of metal between two dies and hits it with a hammer. Works under guard and under oath.", "A moneyer who strikes light coin loses the hand that struck it. The dies are locked up each night, and the moneyers with them, some say."),
        ["jeweller/assayer"] = ("Tests the fineness of gold and silver with a touchstone, acid and a small furnace, and stamps what passes.", "The ruler's coin is tried once a year in public. Gnomes and Lanternkin are hired as assayers because neither is thought to care about gold."),
        ["jeweller/ivory carver"] = ("Carves tusk and tooth into combs, caskets, small figures and the handles of fine knives, with saws, files and fine blades.", "Sunlander carvers serve the palace, and the king has the first tusk of every elephant. The Hoarkin carve walrus tooth through the dark half of the year."),
        ["jeweller/coral carver"] = ("Cuts and polishes branches of red coral into beads, charms and small figures.", "A branch of coral is hung on a child's neck in the south before it is given a name."),
        ["jeweller/amber worker"] = ("Turns and polishes golden amber into beads for prayer strings, and into pendants and inlays.", "The Amberbloods say amber is the blood of their oldest dead and will not see it cut into beads. They buy what they can and bury it."),
        // artist
        ["artist/painter"] = ("Paints panels and walls with pigments ground on a stone slab and bound with egg or oil: holy figures, portraits and arms. A stained smock and a handful of brushes.", "Paid by the foot and by the price of the blue. The contract names how much gold and how many figures, and whether the master must paint the faces himself."),
        ["artist/sculptor"] = ("Carves figures in stone with a mallet and chisels or models them in clay for casting. A yard of half-finished statues, white with dust.", "A patron wants his own face on the saint. The sculptor gives the devil the face of whoever was slow to pay."),
        ["artist/image carver"] = ("Carves holy images and altarpieces in wood, which are then painted and gilded.", "When the faith turns, the images burn first. A carver learns to work for the next temple without comment."),
        ["artist/illuminator"] = ("Paints the pictures, borders and great initials of books with tiny brushes, bright colours and gold leaf.", "In the margins the hares hunt the hounds and the snails joust with knights. Nobody asked the illuminator for that, and nobody has stopped it."),
        ["artist/glass painter"] = ("Paints faces, folds and letters on coloured glass and fires them in, for temple windows.", "Light through the glass is the nearest most people come to seeing paradise. The donor is painted in at the bottom, small, with his arms."),
        ["artist/temple sculptor"] = ("Carves the gods, dancers and beasts that cover a temple from base to tower, working on the stone in place, on a scaffold, for a lifetime.", "Rainkeeper sculptors are born into the work and carve one temple for five generations. The last of them sees it finished and the first is carved on it."),
        ["artist/mosaic maker"] = ("Sets small cubes of stone and coloured glass in wet plaster to make pictures on floors, walls and vaults.", "The craft of the Old Realms, half lost. The best floors left are in ruins, and farmers plough up the cubes."),
        ["artist/map engraver"] = ("Draws coasts, roads and towns from the reports of travellers and cuts them into copper or wood for printing. Works with compass, lens and fine tools.", "Gnome maps are exact, and so rulers forbid their sale. Each engraver puts in one false village, to catch those who copy."),
        ["artist/instrument maker"] = ("Makes instruments of music: harps, lutes, fiddles, pipes and drums, of thin wood, gut and horn.", "An Elven harp takes forty years of seasoning and is strung for one player. When the player dies it is unstrung, and hung in a tree."),
        // artificer
        ["artificer/clockmaker"] = ("Builds clocks of iron and brass wheels driven by weights, for towers and rich houses, and keeps them running.", "A town clock is the council's pride and its standing quarrel with the temple bell. Gnomes made the first, and still set the others by theirs."),
        ["artificer/fine locksmith"] = ("Makes locks with hidden keyholes, false wards and traps, and strongboxes that only their owner can open.", "Dwarven vault locks need three keys and three families. The smith who makes one keeps no drawing and takes an oath on it."),
        ["artificer/instrument maker"] = ("Makes instruments of measure in brass: astrolabes, sundials, compasses, scales and dividers, engraved with fine scales.", "The Gnomes built the instruments of the sorcerer-kings and saw what was done with them. Since then they sell to anyone, and to no one alone."),
        ["artificer/lens grinder"] = ("Grinds and mounts lenses in tubes and frames for far-seeing and near-seeing glasses, and tests them against the stars.", "The first far-seeing glass was offered to a prince for war. The Widegaze laughed at it, and then bought a dozen."),
        ["artificer/tinker"] = ("Travels with a pack of tools and a small brazier, and mends pots, pans, locks and anything of metal at the door.", "Welcome and suspected at every door. Gnome tinkers carry news between the warrens in a speech of their own, and mend the pot while they do it."),
        ["artificer/automaton maker"] = ("Builds figures that move by springs, weights and water, and where there is magic, by a spell: singing birds, striking knights and walking servants.", "The sorcerer-kings had servants of brass, and some are still found, standing in ruins. Nobody has made their like again, and the makers who try are watched."),
        ["artificer/siege engineer"] = ("Designs and builds the engines of a siege: trebuchets, rams, towers and mines. Works from drawings and commands carpenters.", "Paid more than the captain and hated by both sides. A trebuchet is given a name, and it is always a woman's."),
        ["artificer/object enchanter"] = ("Binds a spell into a made thing, a ring, a blade or a lamp, with engraved signs, set stones and long ritual. A bench that is half a smith's and half a mage's.", "A college licenses each enchantment and keeps a register of where it went. An unregistered ring is a crime twice over: once for the maker, once for the wearer."),
        // merchant
        ["merchant/long-distance merchant"] = ("Trades between lands, by ship and caravan, in goods worth their weight: spice, silk, furs and dyes. Richly dressed, travel-worn, and speaks several tongues.", "Saltroad folk carry salt one way and gold the other and have kin at both ends. A caravan's books are kept in a script only the family reads."),
        ["merchant/wholesaler"] = ("Buys by the shipload and sells by the bale from a warehouse, and never from a stall.", "Accused of buying up the market before it opens, which is a crime with three names. The warehouse is where the town's food is, and everyone knows it."),
        ["merchant/draper"] = ("Deals in woollen cloth by the bolt and measures it with a yard rod on a long counter.", "The drapers sit on the council in every cloth town. The weavers who make the cloth do not, and remember it."),
        ["merchant/mercer"] = ("Deals in silk, velvet, fine linen and the small costly wares of dress: ribbons, laces and thread of gold.", "The richest of the guilds in most cities, and the one that lends to kings. A mercer's daughter is a match for a poor knight, and both know it."),
        ["merchant/spicer"] = ("Deals in pepper, ginger, saffron, sugar and drugs, weighed out on small scales from rows of jars and chests.", "Pepper was counted out by the corn and taken as rent. The spicers put it about that it grows guarded by serpents, to explain the price."),
        ["merchant/grain factor"] = ("Buys grain from the country and sells it to the town, and holds it in granaries against the price. Blamed in every hungry year.", "The first house a mob visits in a hungry year. Dwarves, who keep seven years of grain behind the gate, do not sell in the seventh."),
        ["merchant/broker"] = ("Brings buyer and seller together for a fee, owns no goods, and knows every price in the market.", "Sworn to serve both sides and suspected of serving himself. A stranger may only buy in a town through a licensed one."),
        ["merchant/moneychanger"] = ("Sits at a bench with scales and piles of coin, and changes one money into another for a cut.", "Gnomes can tell a clipped coin by its ring on the bench. The word for a bank is the word for that bench, and a broken bench means a failed changer."),
        ["merchant/banker"] = ("Takes deposits, makes loans and writes letters of credit that are paid in a distant city. A counting house with ledgers and an iron chest.", "Lanternkin bankers seal a debt with a vial of their own blood, which glows while they live. A house is trusted for as long as its vials shine."),
        ["merchant/moneylender"] = ("Lends coin against a pledge or a written bond and takes interest. Needed by all and loved by none.", "Every faith forbids usury and every lord needs a loan. So the trade falls to strangers, who are protected until the debt is due and expelled after."),
        ["merchant/insurer"] = ("Takes a fee to bear the risk of a ship or a cargo, and pays if it is lost. Works at a table near the harbour, with contracts and news of every sailing.", "A new trade of the sea ports. The news of a wreck is worth money for an hour, and the insurers pay the fastest riders."),
        // shopkeeper
        ["shopkeeper/retailer"] = ("Keeps a shop on the ground floor of the house, with a shutter that folds down into a counter, and sells by the piece and the ounce.", "The guild fixes what a shop may sell and when it may open. A shop lit after curfew is fined, and the fine is paid by all of them."),
        ["shopkeeper/stallholder"] = ("Sells from a trestle table under an awning on the market square, on the days the market is held.", "A pitch on the square is inherited and fought over by the foot. The same family has stood under the same arch for two hundred years."),
        ["shopkeeper/huckster"] = ("Buys small lots at dawn and sells them dearer through the day from a basket or a tray: eggs, fruit, fish and candles. Often a woman.", "Fined every week for selling dear what she bought cheap that morning. The fine is the town's oldest tax, and nobody means it to stop her."),
        ["shopkeeper/pedlar"] = ("Walks from village to village with a pack on the back, full of needles, ribbons, knives and news.", "Brings needles, ribbons and the news of three valleys. Every village thinks the pedlar a spy, and every lord has used one."),
        ["shopkeeper/chapman"] = ("A travelling dealer with a packhorse or a cart, who sells small wares and buys what the country has to sell.", "Sells the ballads and the cheap books as well as the pins. What the country knows of the world, it knows from the chapman."),
        ["shopkeeper/market trader"] = ("Follows the round of weekly markets and yearly fairs with a cart of goods and a folding stall.", "At a fair the traders have their own court, which sits at once and judges before the dust has settled on their feet."),
        // carter
        ["carter/carter"] = ("Drives a two-wheeled cart behind a horse or an ox, walking beside it with a whip. A smock, a hood and muddy boots.", "Knows every inn, rut and toll for forty miles. Carters carry letters and gossip for nothing, and are trusted with neither."),
        ["carter/teamster"] = ("Drives a heavy four-wheeled wagon behind a team of four or six, and can back it through a gate.", "Speaks to the team in a language of his own. The lead horse wears the bells, and a teamster who needs help on a hill forfeits them."),
        ["carter/muleteer"] = ("Leads a string of loaded mules over tracks no cart can pass, with bells on the lead animal.", "Swears more than any other trade and is forgiven it, since mules understand nothing else. The mountain roads have no other traffic."),
        ["carter/caravan driver"] = ("Walks or rides with a line of camels or other pack animals across desert and steppe, robed and veiled against sun and dust.", "Saltroad folk walk beside the camel rather than tire it. On the worst stretches they travel by night and are led by Duskreader guides."),
        ["carter/caravan master"] = ("Commands a caravan: chooses the way and the wells, deals with tolls and guards, and answers for every bale.", "On the road the master is judge and lord, and a prince travelling with the caravan obeys. A master who loses a well loses his name."),
        ["carter/drover"] = ("Drives herds of cattle, sheep or geese on foot over long distances to market, with dogs and a staff.", "Licensed and bonded, because he is trusted with a district's wealth on the hoof. He carries the money home, so drovers became bankers of a kind."),
        ["carter/porter"] = ("Carries loads on the back, with a frame, a strap across the forehead or a knot on the shoulder, through streets and up stairs.", "The porters' guild holds the quay or the gate by right, and nothing moves that they have not carried. Orcs hold the trade in many ports."),
        ["carter/water carrier"] = ("Carries water from the fountain or the river to the houses, in two pails on a yoke or in a skin on the back.", "The poorest honest trade in a city. At a fire the water carriers are pressed into service, and paid after, if at all."),
        ["carter/courier"] = ("Carries letters and small parcels on foot or on horseback, with a satchel, a staff and the badge of the sender.", "A courier's person is safe by custom in every land. Swiftborn runners are the fastest, and spend their short years on the road gladly."),
        ["carter/post rider"] = ("Rides fast from one post house to the next and changes horses at each, with a horn and a sealed bag.", "The Old Realms kept a horse every ten miles. A few kingdoms keep the posts still, and their kings hear the news a week before their neighbours."),
        ["carter/elephant driver"] = ("Sits on the neck of an elephant and guides it with the feet, the voice and a hooked goad, to haul timber, carry loads or bear a lord.", "Among the Rainkeepers a driver is given to one elephant as a boy, and the two grow old together. An elephant mourns its driver, and may refuse another."),
        // sailor
        ["sailor/seaman"] = ("Works a ship before the mast: hauls ropes, climbs the rigging, rows and bails. Barefoot, in loose trousers, with a knife on a lanyard.", "Paid by a share of the voyage, in most waters, and has a vote on whether to throw the cargo overboard in a storm."),
        ["sailor/ship's master"] = ("Commands a ship and answers for the vessel, the cargo and the crew. Stands at the stern, in a good coat, by the steering oar.", "Often a part owner, and by the sea law the judge, the priest and the notary on board. The law also says when the crew may refuse him."),
        ["sailor/pilot"] = ("Knows one coast or river mouth by heart, its bars, rocks and tides, and guides ships through it with a sounding lead.", "A pilot who loses a ship on his own bar answers for it with his head, by the old sea laws. Shoalfolk pilots see the reef through the water."),
        ["sailor/rigger"] = ("Fits and mends the ropes and spars of a ship, splices and knots, and works aloft without fear.", "Boughwalkers and Catfolk go aloft without a thought and are hired on every ship that can get them."),
        ["sailor/bargeman"] = ("Works a flat barge down a river or along a canal, with a pole, a sweep or a tow horse on the bank.", "Halfling bargemen live aboard with the family, the hens and a garden in tubs, and know every lock-keeper's birthday."),
        ["sailor/boatman"] = ("Rows or poles a small boat for hire, carrying people and goods about a harbour or a town of canals.", "In the cities of the Canal folk the boatmen hear every quarrel and every courtship in the town, and sing over them."),
        ["sailor/ferryman"] = ("Carries travellers, carts and beasts across one river at one place, on a flat boat hauled along a rope or rowed.", "Owns the crossing by an old right and is paid by all, the dead included: in many lands a coin is put in the mouth of a corpse for him."),
        ["sailor/raftsman"] = ("Rides rafts of logs lashed together down a river to the sawmills and the sea, steering with long sweeps.", "The raft is the cargo. The raftsmen ride it for weeks, sell it at the river mouth and walk home."),
        ["sailor/ship's lookout"] = ("Stands in the top of the mast and watches for land, rocks, weather and sails, and calls down what is seen.", "A Widegaze in the top sees nearly the whole horizon at once, and a master who has sailed with one will not sail without."),
        // innkeeper
        ["innkeeper/innkeeper"] = ("Keeps a house with beds, a hall and a stable yard on a road or in a town. Stands at the door in an apron, with a ring of keys.", "A stranger must lodge at an inn by law, and the host answers for the guest's goods and for the guest. He is the first to be questioned and the last to have seen anything."),
        ["innkeeper/taverner"] = ("Sells wine by the cup and the jug in a cellar or a ground-floor room with benches, and keeps the tally in chalk.", "The tavern is the poor man's hall. The watch looks in at curfew, and the taverner's score in chalk is evidence in court."),
        ["innkeeper/hosteller"] = ("Keeps a hostel for pilgrims, merchants or students of one town or one faith, with plain beds in a common room.", "Each nation of merchants has its own house in a foreign port, with its own cook and its own law inside the door."),
        ["innkeeper/alehouse keeper"] = ("Sells ale in the front room of a small house, with a bush or a broom on a pole over the door.", "Mostly a widow, and the alehouse is her pension. The village's quarrels are started and settled on her bench."),
        ["innkeeper/cookshop keeper"] = ("Feeds travellers and lodgers from a common pot and a spit in the kitchen of an inn or a house on the road.", "Halfling innkeepers are judged on the table before the beds, and a traveller plans the road by their kitchens."),
        ["innkeeper/bathhouse keeper"] = ("Keeps a bathhouse with wooden tubs, hot stones and steam, where people wash, are shaved and bled, eat and meet.", "The bathhouse has a worse name than the tavern and more custom. Every plague closes it and every council opens it again."),
        ["innkeeper/stable keeper"] = ("Keeps a yard with stalls, hay and a trough, where travellers leave their animals and hire fresh ones.", "Sells horses on the side, and no one has trusted a horse dealer since the Dawn. He knows who rode in at night, and from where."),
        // healer
        ["healer/physician"] = ("A learned healer in a long gown and a cap, who studies the patient's urine in a glass flask, reads the pulse and the stars, and prescribes.", "Reads the stars and the urine and never touches a knife. A physician is paid whether the patient lives or not, and the patients have noticed."),
        ["healer/surgeon"] = ("Cuts, stitches, sets and burns: treats wounds, breaks, stones and growths with knives, saws, needles and hot irons.", "The Flinchless became the world's surgeons: a people that feels no pain learnt early to look for every wound, and to keep a steady hand."),
        ["healer/barber-surgeon"] = ("Shaves and cuts hair, and also lets blood, pulls teeth and dresses wounds. A striped pole and a basin at the door.", "Travels with armies and learns more in one battle than a physician in a library. The red on the pole is the blood and the white the bandage."),
        ["healer/barber"] = ("Shaves beards and cuts hair with a razor, shears, a comb and a basin of hot water, in a shop full of talk.", "The barber's shop is where a town's news is combed out. A ruler who trusts a man with a razor at his throat tells him things."),
        ["healer/bonesetter"] = ("Sets broken bones and puts joints back by hand, with splints and bandages. A strong grip, learnt in the family and not from books.", "A gift that runs in families, and the college of physicians would like it stopped. People go to the bonesetter first all the same."),
        ["healer/tooth puller"] = ("Pulls teeth in the market place with pliers, before a crowd, with a string of teeth round the neck as a sign.", "Works at fairs with a drummer, to cover the noise. The proverb for a liar is that he lies like one."),
        ["healer/midwife"] = ("Helps women in childbirth, with warm oil, clean linen, a birthing stool and long practice. Trusted with the secrets of every house.", "May christen a child that will not live, and so is licensed by the temple. She knows whose child is whose, and is feared for it."),
        ["healer/nurse"] = ("Tends the sick in a hospital or a house of healing: washes, feeds, changes dressings and watches through the night.", "Hospitals are houses of the faith, and the nursing is done by those under a vow. In a plague the nurses stay when the physicians leave."),
        ["healer/herbalist"] = ("Gathers and dries healing plants and makes them into teas, salves and poultices. Bunches of herbs hang from every beam of the house.", "Elven herbalists have had three human lifetimes to learn the plants. The village herbalist has her grandmother's word, and one accusation between her and the fire."),
        // servant
        ["servant/maid"] = ("A woman servant who sweeps, fetches water, makes the beds and tends the fires. A plain dress, an apron and a linen cap.", "Hired by the year at the autumn fair, with a mop in her hand to show her work. Most leave to marry, with what they have saved."),
        ["servant/manservant"] = ("A man servant who carries, waits at table, runs errands and guards the door, in the livery colours of the house.", "Wears his master's colours and takes his master's quarrels with them. In a great house the livery fights the livery of the house across the street."),
        ["servant/cook"] = ("Rules the kitchen of a household: roasts, boils and bakes for the table of the master, and orders the kitchen boys about.", "The best-paid servant of a great house, and the one a rival tries to hire away. A lord who fears poison is very polite to the cook."),
        ["servant/groom"] = ("Feeds, brushes, saddles and walks the horses of a household, and sleeps in the stable loft.", "Sleeps over the horses and is the first to know when the master rides, and where. Grass riders make the best grooms and the worst servants."),
        ["servant/nurse"] = ("Looks after the children of a household, from the cradle until they are given to a tutor.", "The nurse raises the heir and is kept for life. Great men have been ruled from the nursery long after they left it."),
        ["servant/wet nurse"] = ("Suckles another woman's child for pay, in the family's house or her own. Chosen for health and good temper.", "The child she feeds and her own are milk kin, and in many lands may not marry. A prince's milk brother is the one man he trusts."),
        ["servant/laundress"] = ("Washes linen at the river or in a tub with lye and a beating bat, and spreads it on the grass to bleach. Red, chapped hands.", "The washing place is the women's parliament. A laundress knows a household's linen and so its sicknesses, its births and its guests."),
        ["servant/valet"] = ("Serves one master in person: dresses and shaves him, keeps his clothes and his chamber, and travels with him.", "No man is a hero to the one who dresses him. The valet carries the letters that the secretary may not see."),
        ["servant/page"] = ("A boy of good family who serves in a noble house to learn its manners: carries messages, pours wine and holds the cloak.", "Sent from home at seven to learn another house's manners, and to be a pledge of his father's good conduct."),
        ["servant/taster"] = ("Eats and drinks of every dish before the lord does, as proof against poison. Stands at the lord's shoulder at table.", "Bitterbloods cannot die of a poisoned dish and can name what was in it, so every court that fears the cup hires one. Halflings taste for the pleasure, and for the cook's honour."),
        ["servant/household steward"] = ("Runs a great household: keeps the keys, the stores and the accounts, and hires and commands the other servants. A staff of office and a sober gown.", "Rules a hundred servants and stands behind one chair. A lord's house is as honest as its steward, and no more."),
        // entertainer
        ["entertainer/minstrel"] = ("Sings and plays the lute, the fiddle or the pipe at feasts, fairs and inns. Bright travelling clothes and an instrument slung on the back.", "Classed with vagabonds by the law and seated by the fire by the lord. A minstrel carries news and can pass any gate, which is why half of them are spies."),
        ["entertainer/bard"] = ("A trained poet-singer who keeps the songs, the laws and the lineages of a people in the head, and is honoured for it at a lord's table.", "Twelve years of training, and a satire that can raise blisters on a king. A lord who refuses a bard hospitality is finished in three verses."),
        ["entertainer/harper"] = ("Plays the harp, on the knee or standing, and sings to it. Keeps the instrument in a leather bag and the fingernails long.", "Among the Elves the harper sits beside the lord and is the people's memory. A harper's hands are protected by a law of their own."),
        ["entertainer/singer"] = ("Sings for pay, alone or in a choir: in a temple, at a court or in the street.", "A good voice lifts a peasant's child into a temple choir, and from there to anywhere. It is the one ladder with no toll."),
        ["entertainer/drummer"] = ("Plays drums for dances, processions and war, and in some lands sends news from village to village by drum.", "Sunlander drums speak: a message crosses a kingdom in a day. Certain drums belong to the king alone, and are fed like guests."),
        ["entertainer/praise-singer"] = ("Sings the deeds and the ancestors of a patron, from memory, at every public moment. Can make a name, and unmake it.", "A hereditary class among the Sunlanders, who keep the genealogies and may say anything. A king without a praise-singer has no past."),
        ["entertainer/storyteller"] = ("Tells tales to a ring of listeners in a market or a coffee house, with voice and gesture, and stops for coins at the best moment.", "Stops at the moment of greatest danger and passes the bowl. The tale has been going for forty nights, and the listeners know it by heart."),
        ["entertainer/poet"] = ("Makes verses to order for weddings, victories and funerals, and recites them. Lives on the gifts of patrons.", "Northmen pay a poet in gold rings and remember the price in the next poem. A bad verse about a king has cost a poet his head, and a good one has bought it back."),
        ["entertainer/actor"] = ("Plays parts on a cart or a scaffold stage, in masks and borrowed finery, with a travelling company.", "Refused burial in holy ground in some lands and kept by kings in others. Swiftborn players learn a part in a night and have played every age of a life by twenty."),
        ["entertainer/acrobat"] = ("Tumbles, juggles, balances and walks on the hands in the street and at feasts, in tight bright clothes.", "A family trade, taught from the cradle. The preachers call it the devil's and the crowd pays to see for itself."),
        ["entertainer/rope dancer"] = ("Walks, leaps and dances on a rope stretched high between two poles or towers, with a long pole for balance.", "Catfolk walk the rope as others walk a street, and the troupes would rather hire one than train ten."),
        ["entertainer/dancer"] = ("Dances for an audience, alone or in a troupe, to drum and pipe, in flowing clothes with bells at the ankles.", "Rainkeeper temple dancers are born to it and are wed to the god. Elsewhere the dance is for a wedding, and everyone joins in by the third cup."),
        ["entertainer/jester"] = ("A lord's fool: mocks, jokes and tumbles, in a motley coat and a cap with bells, with a bauble on a stick. May say what no one else dares.", "The fool alone may tell the king the truth, and must make him laugh while he does. An old fool is kept on, like an old hound."),
        ["entertainer/wrestler"] = ("Fights for prizes at fairs and courts, by grip and throw. Thick-necked, stripped to the waist and oiled or belted.", "Grass riders hold wrestling as one of the three skills of a man. Hearthbloods wrestle in the snow to keep warm, and villages bet a winter's grain on them."),
        // courtesan
        ["courtesan/courtesan"] = ("A companion of the rich, admired for wit, music and beauty, who keeps a fine house and chooses the guests. Dressed above the law's allowance.", "Educated beyond any wife of the city. Ministers visit her salon to hear what other ministers said, and she is taxed more than a merchant."),
        ["courtesan/companion"] = ("Hired to keep company at table, on a journey or through an evening: talks, plays, sings and listens.", "Hired for conversation, and good at it. A Stillface companion gives nothing away by the face, which half the clients find restful and half unnerving."),
        ["courtesan/kept mistress"] = ("Lives in a house paid for by one lover, outside marriage, with servants and fine clothes, for as long as the favour lasts.", "Has everything but a contract. A wise one buys the house in her own name within the first year."),
        ["courtesan/prostitute"] = ("Sells the bed in a licensed house or a back street, and wears the mark the town lays down: a striped hood, a yellow ribbon.", "Licensed, taxed, marked by law and preached against, often by the same council in the same year. The town's rent from the house repairs its bridge."),
        ["courtesan/bathhouse attendant"] = ("Serves in a bathhouse: carries water, scrubs backs, brings wine, and for a coin more keeps the guest company.", "The bathhouse guild insists its members only scrub backs. The town clerk records the insistence each year."),
        ["courtesan/brothel keeper"] = ("Runs a public house of the trade: holds the licence, the keys and the debts of those who work there.", "Holds the lease from the town, the bishop or a lord, and pays the watch not to look. Holds the debts of those inside, which is the real lock on the door."),
        // noble
        ["noble/lord"] = ("Holds a castle or a manor and the land around it, judges its people and leads them in war. Fur-lined robes, a signet ring and a sword.", "Holds his land of someone, and someone holds of him: every lord is another's man. He may hang a thief and may not work with his hands."),
        ["noble/lady"] = ("A noblewoman who rules the household and, when the lord is away, the estate. A long gown, a veil or a headdress, and the keys at her belt.", "Holds the castle when the lord is away, which is often, and has held it against sieges. Her seal is as good as his, and her memory for kinship is better."),
        ["noble/knight"] = ("A mounted warrior of noble rank, in mail or plate, with lance, sword and a shield painted with his arms. Sworn to a lord and bound by honour.", "The Midlanders made the knight their ideal: a horse, a harness, a code, and debts to pay for the first two. The songs and the facts have little to say to each other."),
        ["noble/squire"] = ("A young noble who serves a knight, carries his shield, tends his horse and armour, and trains to become one.", "Seven years of carrying another man's shield. Many stay squires for life, because knighthood costs more than the land brings in."),
        ["noble/landholder"] = ("A lesser noble with one manor: lives on its rents, rides to the hunt, and sits as a justice in the district.", "The backbone of every county and the despair of every king: too many to ignore, and too poor to buy."),
        ["noble/chief"] = ("The head of a clan or a tribe, by birth and by the consent of the elders. Known by a staff, a cloak or a headdress, and sits in the high seat of the hall.", "Among the Orcs the chief leads in war and the hearth-mother rules in peace. A chief who loses the elders loses the hall."),
        ["noble/jarl"] = ("A northern lord of ships and halls, in a fur cloak, with gold rings on the arms. Feasts his sworn warriors and leads them over the sea.", "A Northman jarl is as great as his generosity: a ring-giver. A jarl who hoards is left by his men within the winter."),
        ["noble/khan"] = ("The lord of a herding people of the open plains. Rules from the saddle and from a great felt tent, in silk and fur, with a banner of horse tails.", "Raised on a felt carpet by the assembly of the Grass riders. Every few generations one khan is raised over all the others, and the settled lands learn his name."),
        ["noble/title-holder"] = ("Holds a title and a seat on a council by rank or purchase. Known by the staff, the cap, the beads or the stool of the title.", "Among the Sunlanders the title-holders sit as a council that can depose a king. A title is earned, bought or inherited, and each must be fed with gifts."),
        ["noble/head of a great house"] = ("Leads a great family, its lands, its marriages and its feuds, and speaks for it before the ruler. Wears the arms of the house and its oldest jewels.", "The Twofold give the house to its eldest, who has been both its son and its mother, and count that the only way to know a family."),
        // official
        ["official/steward"] = ("Runs a lord's lands in his name: rides between manors, holds the manor court and audits the accounts. Well dressed, with a staff of office and a clerk.", "The lord's other self, and often his creditor. A steward who has served three lords of a house knows more of it than any of them did."),
        ["official/bailiff"] = ("The lord's man on one manor: sees the work done, collects the rents and seizes the goods of those who do not pay.", "The face of the lord that the village actually sees. The risings begin by burning the bailiff's rolls, and sometimes the bailiff."),
        ["official/reeve"] = ("A villager chosen for the year to oversee the lord's harvest and answer for it. A peasant with a white rod and a tally stick.", "A peasant set over peasants for a year, who answers with his own goods for the lord's harvest. No one wants the office and no one may refuse it."),
        ["official/hayward"] = ("Guards the hedges, the crops and the common meadow against straying beasts, and blows a horn at a trespass.", "Takes straying beasts to the pound and is cursed for it. His horn at harvest is the signal to begin, and his sheaf is the first."),
        ["official/magistrate"] = ("Keeps the peace of a town or a district: hears small cases, fines, and sends the rest to the judge.", "Canal folk magistrates are chosen by written examination and sent far from home, so that they have no cousins to favour."),
        ["official/judge"] = ("Hears cases and gives sentence in the ruler's name, from a raised seat, in a robe and a cap, with a clerk writing below.", "Sits with one empty seat beside him for the ruler whose justice it is. Dwarven judges read the written grudge back to both sides before they begin."),
        ["official/tax collector"] = ("Goes from door to door with a list, a clerk and a guard, and takes the ruler's due in coin or kind.", "Farms the tax: pays the ruler a sum and keeps what more he can raise. No trade is more hated, and none is bid for so keenly."),
        ["official/toll keeper"] = ("Sits at a bridge, a gate or a ford with a bar across the road, and takes a coin for every cart and beast.", "Every bridge and ford has its toll and its story of the traveller who would not pay. Merchants count a road by its tolls, not its miles."),
        ["official/customs searcher"] = ("Goes through ships and bales at a harbour or a border for goods that owe duty, with a probing rod and a seal.", "Takes a share of what he seizes, and a present for what he does not. Smugglers budget for the searcher as for the freight."),
        ["official/weigh-master"] = ("Keeps the public scales of a market, weighs goods for a fee, and stamps the weights that are true.", "The town's weights are kept in the temple, and false ones are nailed to the door of the weigh house with their owner's name."),
        ["official/sworn measurer"] = ("Measures grain, cloth, wine and land under oath, with the town's own measures, and settles quarrels over quantity.", "A heaped bushel or a struck one: riots have begun over the difference. The measurer's oath is taken on the standard measure itself."),
        ["official/surveyor"] = ("Measures land with a chain and rods, sets boundary stones and draws the plan.", "The boundaries are walked each year with the village boys, who are bumped on each stone so that they will remember it."),
        ["official/mayor"] = ("The head of a town council, chosen by its leading citizens. A chain of office, a furred gown and the town seal.", "Chosen for a year by the guilds, and usually from the same six families. A mayor answers to the lord for the town and to the town for the lord."),
        ["official/herald"] = ("Knows every coat of arms, carries a lord's messages in war and peace, and proclaims at tournaments. Wears a short coat with the lord's arms.", "A herald is safe on any battlefield, and counts the noble dead afterwards by their arms. He decides who may bear what, and is paid for deciding."),
        ["official/town crier"] = ("Calls out news and orders in the streets, with a bell or a drum and a loud voice.", "What the crier has called three times is law, and no one may plead that they did not hear. To strike a crier is to strike the town."),
        ["official/envoy"] = ("Carries a ruler's words to another court and brings back the answer, with letters, gifts and a small retinue.", "An envoy's person is sacred, and killing one is the oldest cause of war. Lanternkin envoys carry their sovereign's word and their own glowing pledge of it."),
        ["official/treasurer"] = ("Keeps the chest and the accounts of a ruler, a town or a temple, and counts coin on a chequered cloth.", "Accounts are reckoned on a chequered cloth with counters, before witnesses. The treasurer is the minister most often hanged at a change of reign."),
        ["official/gaoler"] = ("Keeps the prison: locks, feeds and guards those held, and takes fees from them for every comfort. A ring of great keys.", "Unpaid by the town: he lives on what the prisoners pay for a bed, a fire and lighter irons. A rich man's prison is an inn with a lock."),
        // soldier
        ["soldier/man-at-arms"] = ("A trained fighter in mail and plate, on foot or mounted, with sword, shield and poleaxe. Serves a lord for pay or land.", "The Midlanders' wars are fought by a few hundred of these and their followers. A harness costs a farm, and is stripped from the dead before they are cold."),
        ["soldier/archer"] = ("Shoots a long bow as tall as a person. A padded jacket, an open helmet, a bracer on the arm and a sheaf of arrows at the belt.", "The Elves put every one of their people behind a bow, and so a few hold a forest against many. Among the Midlanders the yeoman must practise every feast day by law."),
        ["soldier/crossbowman"] = ("Shoots a crossbow, spanned with a hook or a crank, from behind a tall standing shield. Carries a quiver of short bolts.", "A weapon that lets a townsman kill a knight, and so it was banned by the temple, and hired by every prince. The best companies come from the port cities."),
        ["soldier/spearman"] = ("Fights in a close rank with a long spear and a shield, in a padded coat and an iron cap.", "The levy of every people: a spear, a shield and a neighbour on each side. Orc spears held the lines of the fallen Realms, and are still for hire."),
        ["soldier/mounted archer"] = ("Shoots a short recurved bow from the saddle at the gallop, in any direction. A light coat, a quiver at the hip and a string of spare horses.", "A Grass rider shoots at the moment all four hooves are off the ground. The settled peoples have never found an answer except a wall."),
        ["soldier/cavalryman"] = ("Fights on horseback with lance and sword, in armour of mail, scale or quilted cloth, the horse often armoured too.", "The Sunlander kingdoms of the long grass ride in quilted armour, horse and man. The cavalry is the king's, and the horses die of the forest fly further south."),
        ["soldier/sergeant"] = ("A veteran who keeps a small troop in order, in the line and in camp. Carries a halberd or a staff and a loud voice.", "A captain commands the company and the sergeant runs it. He is the one the recruits fear and the one the old soldiers follow."),
        ["soldier/captain"] = ("Commands a company, hires it out and divides the pay. Better armour, a sash or a plume, and a clerk for the muster roll.", "Signs the contract, draws the pay and answers for the company's deeds, to the paymaster, if not to the law. Some captains end as lords of what they were hired to defend."),
        ["soldier/mercenary"] = ("Fights for whoever pays, in a company under its own banner and law. Gaudy, slashed clothes, mismatched armour and old scars.", "A free company fights for the contract and not a day longer. Orcs and Dwarves both hire out, and neither has ever been bought twice in the same war."),
        ["soldier/drill master"] = ("Trains recruits to stand, march and strike as one, on the drill yard, with a staff and endless repetition.", "The Flinchless are bred from a legion and drill as others pray. A man who cannot feel a blow must be taught to notice one."),
        ["soldier/marine"] = ("A soldier who fights from ships: boards over the rail and shoots from the fighting tops. Light armour, a short sword and a boarding axe.", "Paid a share of the prize, and so keen to take a ship whole. Northmen do not have the word: every one of their sailors is one."),
        ["soldier/champion"] = ("Fights single combats for a lord, an army or a party in a trial by battle. The best armed and most feared of a host.", "Trial by battle lets the old, the sick and the temple hire one to fight in their place. A champion who loses is fined as a perjurer."),
        // guard
        ["guard/watchman"] = ("Keeps watch over a place by day or night, with a staff, a lantern and a rattle or a horn to raise the alarm.", "Every householder owes his turn at the watch, and the rich pay a poor man to take theirs. So the watch is old, cold and easily bought."),
        ["guard/town guard"] = ("Keeps order in the streets in the town's colours, with a halberd or a club, a helmet and a padded coat.", "Paid by the council and loyal to whoever is in it. The guard knows every thief in the ward by name and arrests the ones who are behind with their dues."),
        ["guard/gate guard"] = ("Stands at a town gate, looks over those who enter, and closes the gate at dusk. A spear, a helmet and a brazier in winter.", "The gate closes at dusk and a late traveller sleeps outside, whoever he is. The gate guard's small door opens for a coin, as everyone knows."),
        ["guard/night watch"] = ("Walks the dark streets in a small band after curfew, with lanterns and staves, and calls the hours.", "Duskreaders see a warm body in the dark, and Catfolk hear one. A town with either on its night watch is a bad town for a burglar."),
        ["guard/bodyguard"] = ("Stays within arm's reach of one person and stands between that person and harm. Well armed, watchful and silent.", "Rulers choose their guard from far away: a stranger has no cousin with a claim. Northmen serve southern courts as sworn guards, and the Flinchless stand where the blade will come."),
        ["guard/caravan guard"] = ("Rides with a caravan for a season's pay, armed with bow and spear, and sleeps by the bales.", "Hired at one end of the road and paid at the other, so that he arrives. In the worst country the guards are hired from the bandits' own people."),
        ["guard/road warden"] = ("Patrols a stretch of road on horseback against robbers, and helps travellers in trouble.", "The Widegaze patrol the plains roads and see a robber band a day off. Where there is no warden, the merchants pay the robbers directly."),
        ["guard/pass warden"] = ("Holds a mountain pass from a small tower: takes the toll, guides travellers over and brings them down from the snow.", "Hearthbloods hold the high passes, where no one else can winter. Midlanders and Northmen pay them as wardens and fear them in a hungry year."),
        ["guard/lookout"] = ("Watches from a tower or a hilltop for sails, smoke and riders, and signals with a horn, a flag or a mirror.", "A Widegaze on a tower is worth a troop on the wall, and they sell the service to every side."),
        ["guard/beacon keeper"] = ("Tends a pile of wood and pitch on a height, ready to light it as a warning fire or to guide ships.", "A chain of fires carries a warning across a kingdom in a night. The keeper who lights it without cause hangs, and so does the one who sleeps."),
        ["guard/granary warden"] = ("Guards a town's grain store against thieves, fire, damp and vermin, and sleeps beside it.", "Catfolk cannot eat grain, so every city trusts them to guard it. They take their pay in meat and in the rats."),
        ["guard/vault keeper"] = ("Guards a treasury behind iron doors and many locks, and knows who may enter and what lies on each shelf.", "Among the Dwarves the office passes within one family, and the keeper may refuse the lord himself entry without the second key."),
        ["guard/firefighter"] = ("Watches for fire from a tower and fights it with leather buckets, ladders, axes and long hooks to pull down burning thatch.", "The Flinchless go into a burning house without a thought, and are counted and examined when they come out, since they do not know when they are burnt."),
        // priest
        ["priest/village priest"] = ("Serves one village and its small temple: leads the rites, blesses fields and marriages, buries the dead, and farms a field of his own. A plain robe and worn shoes.", "A farmer's son with a little learning, who ploughs his own strip and knows every sin in the parish. The village pays him in eggs."),
        ["priest/temple priest"] = ("Serves in a great temple, one of many under a high priest: tends the altar, the lamps and the offerings, in rich vestments on feast days.", "A great temple is a great estate, and its priests are landlords, bankers and judges. The high priest is a lord's younger son, more often than not."),
        ["priest/chaplain"] = ("The priest of a lord's household, a ship, a guild or a company of soldiers. Says the rites and often writes the letters.", "Reads and writes for a lord who can do neither. He hears the lord's confession, and so is never dismissed."),
        ["priest/shaman"] = ("Speaks with spirits for a people, in a trance, with a drum and a rattle. A coat hung with bones, feathers and iron charms.", "Among the Grass riders the shaman rides to the sky on the drum and may rebuke the khan. The calling comes as a sickness, and nobody asks for it."),
        ["priest/monk"] = ("A man who lives under a rule in a monastery: prays at the set hours, works and copies books. A coarse habit with a hood and a rope belt.", "The monasteries kept the books through the Ashen Years, and the seed corn. They have been rich ever since, and reformed every century."),
        ["priest/nun"] = ("A woman who lives under a rule in a convent: prays at the set hours, sews, teaches and nurses. A plain habit and a veil.", "The one life where a woman may read, rule an estate and answer to no husband. Great ladies retire to a convent, and some govern from it."),
        ["priest/friar"] = ("A brother of a begging order who walks the roads and preaches in the market place. A patched habit, sandals, a staff and a bowl.", "Sworn to own nothing, and welcome in the towns for it. The parish priests hate them for hearing confessions more cheaply."),
        ["priest/hermit"] = ("Lives alone in a hut or a cave to pray, on what visitors bring. A long beard, a rough robe, and often a tame animal.", "The village feeds its hermit and asks advice in return. A lord builds a hermitage in his park and hires a man to fill it."),
        ["priest/ascetic"] = ("Has given up every comfort for holiness: nearly naked, smeared with ash, thin from fasting, with matted hair.", "Rainkeepers hold that the last stage of a good life is to walk away from it. Kings come out to bow to men who own nothing."),
        ["priest/sexton"] = ("Keeps a temple and its graveyard: rings the bell, lights the lamps, sweeps the floor and digs the graves.", "Knows who lies where, and who was put there in a hurry. The sexton's spade and the sexton's tales are both older than he is."),
        // scribe
        ["scribe/clerk"] = ("Writes and keeps records for a lord, a court or a merchant. A pen case and an ink horn at the belt and ink on the fingers.", "Half a priest: tonsured, and tried only by the temple's court. A man who can read a verse aloud may claim to be one and save his neck."),
        ["scribe/copyist"] = ("Copies books by hand at a sloped desk, line by line, with a quill in one hand and a knife in the other.", "Paid by the line. At the end of a book the copyist writes his own words: the work is done, give the writer a drink."),
        ["scribe/notary"] = ("Draws up contracts, wills and deeds in the right form and marks them with a personal sign that makes them valid.", "Lanternkin notaries mix a drop of their blood into the ink: the signature glows while the notary lives, and the world's contracts rest on it."),
        ["scribe/bookkeeper"] = ("Keeps a merchant's accounts in ledgers, with a counting board or an abacus, and balances them at the year's end.", "The Saltroad folk kept the books when everyone else burned theirs, and their way of writing every sum twice is the one all merchants use."),
        ["scribe/secretary"] = ("Writes the letters of one master, keeps his seal and his secrets, and travels with him.", "The keeper of secrets, as the word says. A ruler's secretary writes in the ruler's own hand, and has done so in the ruler's absence."),
        ["scribe/advocate"] = ("Pleads cases before a court for a fee, in a long robe, with a bundle of papers and a ready tongue.", "Paid by both the winner and the loser, and so never out of pocket. The saint of the lawyers is admired for having been an honest one."),
        ["scribe/records clerk"] = ("Keeps an archive: rolls, charters and registers on shelves and in chests, and finds the one that proves a right.", "Dwarves keep every contract and every grudge in writing, and the clerk who can find a deed six hundred years old is a power in the hold."),
        ["scribe/printer"] = ("Sets small metal letters in a frame, inks them and pulls sheets on a wooden screw press. Fingers black with ink.", "The Canal folk print from carved blocks and from clay letters. Elsewhere the copyists' guild has had presses broken, and then bought one."),
        ["scribe/bookbinder"] = ("Folds and sews the written or printed sheets of a book onto cords and laces them into boards, ready for the cover.", "A book is sold as loose sheets, and bound to the buyer's purse. The binder is the first to read it whole, and the only one who never has time."),
        ["scribe/bookseller"] = ("Sells and lends books from a small shop near a temple or a school, and orders copies made.", "Sworn to the college, which fixes the price and inspects the copies. The forbidden books are in the back, and cost double."),
        ["scribe/witness for hire"] = ("Attends deals, oaths and handings-over for a fee, remembers exactly what was seen and said, and swears to it before a court.", "A Widegaze sees the whole room at once and forgets nothing of it. Courts in the plains will take the word of one against three others."),
        // scholar
        ["scholar/teacher"] = ("Teaches a craft of the mind to those who come: reading, reckoning, law or the holy books, wherever there is a room and pupils.", "Paid by the pupil and by the week, and so always hungry in summer. The Twofold say no one should teach before living both halves of a life."),
        ["scholar/schoolmaster"] = ("Keeps a school for boys, teaches them their letters and the old tongue, and keeps order with a birch rod.", "Teaches the old tongue of the Realms with a rod. Every great man remembers his schoolmaster, and few fondly."),
        ["scholar/tutor"] = ("Lives in a rich house and teaches its children alone, in manners as much as in letters.", "Elves serve as tutors at human courts, and have taught the grandfather, the father and the son the same lesson with the same result."),
        ["scholar/professor"] = ("A master of a college, who lectures from a raised chair to benches of students, in a gown and a cap.", "A college of masters answers to no town court and may go on strike. When it does, it walks out and founds another city's college."),
        ["scholar/sage"] = ("Old and learned in many things, sought out for counsel by rulers and common folk. Lives simply among books and scrolls.", "The Orcs call theirs the greybacks, and a war band does not ride without asking one. Elsewhere a sage is someone a king consults too late."),
        ["scholar/astronomer"] = ("Watches the sky at night from a roof or a tower with an astrolabe and a quadrant, and keeps tables of the stars and the calendar.", "The Saltroad folk named most of the stars. The Noonfolk, who sleep at sunset, have never seen one, and take astronomy on trust."),
        ["scholar/mathematician"] = ("Works with number and figure, on a slate, a sand tray or paper: reckons calendars, taxes, vaults and the paths of the stars.", "The Rainkeepers have a sign for nothing, and reckon with it faster than anyone. Tax, temple and reservoir are all sums."),
        ["scholar/lore keeper"] = ("Keeps the old knowledge of a people, in memory or in ancient books, and teaches it to a chosen few.", "Elven lore keepers remember the Dawn at second hand, from someone who was there. They correct the histories of others, tiresomely, and are right."),
        ["scholar/chronicler"] = ("Writes down year by year what happens in a realm, a town or a monastery, from what is seen and what is told.", "Swiftborn chroniclers write a generation every ten years and keep the fullest annals in the world. Everyone else's chronicle begins with the Ashen Years."),
        ["scholar/librarian"] = ("Keeps a library: chains the books to the desks, lists them, mends them and decides who may read.", "Books are chained, and a curse is written in each against the thief. The librarian adds to the curse from experience."),
        ["scholar/keeper of genealogies"] = ("Keeps the family trees of a people, in long rolls or by heart, and settles who is kin to whom and who inherits.", "Halflings know their cousins to the ninth degree and will recite them at dinner. An inheritance is settled by the keeper before it reaches a court."),
        // mage
        ["mage/wizard"] = ("A learned mage, trained for years from books: a long robe, a staff, a pouch of components and a tower room full of scrolls and instruments.", "Ten years in a college, an oath to it for life, and a ruler and a temple watching. The sorcerer-kings were wizards once, and no one has forgotten."),
        ["mage/sorcerer"] = ("A mage by birth and not by study: the power comes unasked and shows in the eyes or the hands. Often young, untaught and feared.", "A village fears the child and a college claims it. Those the college does not find in time are found by a cabal, or by a mob."),
        ["mage/enchanter"] = ("Works on minds and on things: charms, illusions and lasting spells laid on places and objects. Soft-spoken and richly dressed.", "The law of most lands voids a contract made under a charm, and so every notary keeps a test for one. A proven charm on a ruler is treason."),
        ["mage/court mage"] = ("A ruler's own mage: advises, wards the palace, reads the signs and stands near the throne. Fine robes and the ruler's badge.", "The first to be blamed when the harvest fails and the last to be dismissed. A court mage serves the throne, and reports to the college."),
        ["mage/battle mage"] = ("A mage trained for war: throws fire and lightning, breaks gates and shields the line. Wears a robe over armour, with a staff shod with iron.", "A captain pays a mage ten soldiers' wages and guards him with twenty. The colleges forbid their members to face each other in the field, and the oath mostly holds."),
        ["mage/hedge wizard"] = ("A self-taught country mage with a few true spells, who mends, finds and wards for farmers in return for food.", "Unlicensed, half taught and useful. The college calls them a danger, and the village calls them when the well goes sour."),
        ["mage/rune carver"] = ("Cuts signs of power into stone, wood, bone and iron, and reddens them, so that the thing is bound to a purpose. Carries chisels and a knife.", "Northmen say the runes were won by hanging nine nights on a tree. A carver who cuts a rune he does not understand does harm, and the stones say so."),
        // alchemist
        ["alchemist/apothecary"] = ("Keeps a shop of drugs, spices and sweets in rows of labelled jars, and mixes what the physician prescribes with a mortar and small scales.", "Sells sugar, spice, drugs and poison over one counter, and is inspected by the physicians, who hate the trade and need it."),
        ["alchemist/alchemist"] = ("Seeks to turn one substance into another, and lead into gold, with furnace, still and retort, in a cluttered and smoky workroom.", "Princes keep them like hawks and hang them, in a gilded robe, when the gold does not come. What they find by the way has been worth more."),
        ["alchemist/potion maker"] = ("Brews draughts that work, where there is magic: for healing, strength, sleep or love, sealed in small stoppered flasks.", "A college seals each flask and answers for it. An unsealed potion is cheaper, and has made some widows and a few fortunes."),
        ["alchemist/antidote maker"] = ("Prepares cures for venoms and poisons, and sells them to courts that fear the cup.", "The Bitterbloods were bred as tasters, became poison themselves, and now sell the cure. They price it by what the buyer fears."),
        ["alchemist/poisoner"] = ("Prepares poisons from plants, minerals and venoms, and knows the dose, the taste and the delay of each. Sells with no questions asked.", "Called a seller of inheritance powder. The Bitterbloods keep a hidden school of the art, which most of their own people would like to see closed."),
        ["alchemist/perfumer"] = ("Distils the scents of flowers, resins and musk into oils and waters, and blends them in tiny bottles.", "Stillfaces speak by scent and compose perfumes as others write letters. What a court wears as fashion, a Stillface reads as a sentence."),
        ["alchemist/embalmer"] = ("Prepares the dead to last: washes, opens and fills the body with salts, resins and spices, and wraps it in linen.", "Brinefolk learned to keep their dead in the salt of their dried sea. Other peoples hire them for kings, and stand well back."),
        ["alchemist/maker of insect smoke"] = ("Makes coils, cakes and powders that burn with a smoke that drives off flies and fever-bearing midges, in swamp and jungle country.", "A Bitterblood craft of the fever swamps. A town that burns the smoke each dusk loses fewer children, and does not ask what is in it."),
        // seer
        ["seer/diviner"] = ("Reads the answer to a question in thrown bones, shells, sticks or the entrails of a beast, on a mat or a marked tray.", "Sunlander diviners serve a king's court and a farmer's doubt with the same sixteen figures. The client does not say the question aloud."),
        ["seer/astrologer"] = ("Casts the chart of the heavens for a birth or a decision, from tables and an astrolabe, and names the lucky and unlucky days.", "No Rainkeeper marries, sows or builds without the chart. The court astrologer's forecast of a king's death is treason, even when asked for."),
        ["seer/geomancer"] = ("Reads the land and its hidden currents, and says where a house, a grave or a town should stand and which way it should face.", "The Canal folk will not dig a grave or a canal without one. A family's luck is in its ancestors' graves, and lawsuits are fought over a hill."),
        ["seer/soothsayer"] = ("Foretells for a coin at a market or a gate, from the palm, the face or a flight of birds.", "Tells a traveller what a traveller wants to hear. Now and then one tells the truth by mistake, and is run out of town for it."),
        ["seer/oracle"] = ("Speaks for a god or a spirit at a holy place, in a trance, in riddling words that priests write down.", "Kings send to the oracle before a war and hear what both sides can read as victory. The priests who write the answer down are the ones to bribe."),
        ["seer/medium"] = ("Lets the dead and the spirits speak through the mouth, in a darkened room, for those who mourn or need an answer.", "The temple forbids it and the bereaved come anyway. What speaks is not always the one who was called."),
        ["seer/dowser"] = ("Walks the ground with a forked hazel twig that dips over hidden water, ore or lost things.", "The miners swear by the rod and the scholars cannot make it work. The dowser is paid only on a strike, and is paid often enough."),
        ["seer/well-finder"] = ("Finds water in dry land, by signs in the sand, the plants and the stars, or by a sense others lack, and marks where to dig.", "Duskreaders see where the cool of water lies under hot sand. They have sworn to keep quiet about how, and the Saltroad folk pay them not to explain."),
        ["seer/weather watcher"] = ("Reads the sky, the wind and the beasts and says what weather comes, for sowers, herders and sailors.", "The Widegaze see a storm a day before it breaks and move the herds. A harbour pays its watcher a share of every ship that did not sail."),
        ["seer/wise woman"] = ("An old woman of the village who knows herbs, births, charms and omens, and is asked before the priest is.", "Called to every birth and every deathbed. The priest tolerates her until the bishop visits."),
        ["seer/hedge witch"] = ("Lives at the edge of the village, with a cat, a cauldron and a garden of strange plants, and makes charms, cures and curses.", "Feared in daylight and visited after dark. When the cattle die she is the first to be named, by the same people who bought the charm."),
        ["seer/cunning man"] = ("A village man who finds thieves and lost goods, lifts curses and names witches, with a book, a sieve and a pair of shears.", "Makes his living from undoing witches' work, and so needs witches. He names one when business is slow."),
        // labourer
        ["labourer/day labourer"] = ("Waits at the hiring place each dawn and takes whatever work is offered for the day. A worn tunic and bare hands.", "Stands at the cross each dawn with the tool of his trade in his hand. After the plague the law fixed the wage, and no one has ever been paid it."),
        ["labourer/field hand"] = ("Works another's fields through the year for a wage and a meal: hoes, weeds, spreads dung and threshes.", "Noonfolk work from first light to last and need no dinner: they live on the sun. They lie down where they stand at sunset, and farmers plan the day around it."),
        ["labourer/harvest hand"] = ("Hired for the weeks of harvest: reaps with a sickle or mows with a scythe, binds the sheaves, and moves on.", "Swiftborn gangs follow the harvest north through the summer. They have thirty years in all, and do not spend one idle."),
        ["labourer/builder's labourer"] = ("Mixes mortar and carries stone and brick up the ladders in a hod, for the masons on the scaffold.", "Carries a ton up the ladders in a day, for a third of the mason's wage. The one who falls is not named in the accounts."),
        ["labourer/digger"] = ("Digs with spade and pick wherever earth must be moved: foundations, moats, cellars and banks.", "Every castle moat and city ditch was dug with a wooden spade by men like these. Orcs dig for hire, and are fed from the same pot as the soldiers."),
        ["labourer/ditcher"] = ("Cuts and clears the ditches and drains of fields and roads, standing in water in long boots.", "Hedging and ditching are winter work, when nothing else pays. Fen country lives or drowns by its ditchers."),
        ["labourer/dock hand"] = ("Loads and unloads ships at the quay: rolls barrels, carries sacks and works the treadwheel crane.", "Hired by the tide at the quay gate, and loyal to the gang. A port's strikes begin here, and a port's smuggling."),
        ["labourer/quarry hand"] = ("Clears rubble, hauls sledges and turns the windlass in a quarry, under the orders of the quarriers.", "Works beside the convicts and is told from them only by going home at night."),
        ["labourer/peat cutter"] = ("Cuts bricks of peat from a bog with a long narrow spade and stacks them in small heaps to dry.", "Each household has its bank on the bog by right. Now and then the spade turns up a body from the Dawn, tanned like leather, and it is put back with a prayer."),
        ["labourer/ice cutter"] = ("Saws blocks of ice from a frozen lake in winter and hauls them to an ice house packed with straw.", "Hearthbloods cut ice for the pleasure of the cold, and sell it in the south for the price of wine."),
        ["labourer/gravedigger"] = ("Digs the graves and fills them in, with a spade and a pick, and buries the poor and the plague dead that no one else will touch.", "Digs the grave before he knows who it is for, the saying goes. In a plague he is the one man in town who is never short of work or company."),
        // beggar
        ["beggar/beggar"] = ("Sits at a temple door or a bridge in rags, with a bowl and a staff, and asks for alms.", "Alms are a duty in every faith, and so the beggar does the giver a service. Good pitches are owned, inherited and rented out."),
        ["beggar/pauper"] = ("Too poor to live without help, and on the parish's or the temple's list for bread and a little coin.", "The honest poor, known to their neighbours and entered on a list. The list is read out, which is the price of the bread."),
        ["beggar/vagrant"] = ("Wanders from place to place with no home, no master and no trade, and is whipped on by every town.", "A masterless man is an offence in himself. The law brands him at the first town, whips him at the second and hangs him at the third."),
        ["beggar/almsman"] = ("An old or worn-out person housed and fed by a charity, in return for prayers for the founder. A plain gown with a badge.", "Wears the founder's badge and prays for the founder's soul at fixed hours. A place in the almshouse is in a lord's gift, and is asked for years ahead."),
        ["beggar/cripple"] = ("Cannot work for a lost or twisted limb, blindness or sickness, and begs on a crutch, a low wheeled board or behind a guide.", "Old soldiers, mostly. Some sores are painted on, and the beggars' brotherhood teaches how, and takes a share."),
        ["beggar/pilgrim"] = ("Walks to a holy place on a vow and lives on alms along the way. A broad hat, a staff, a scrip and the badge of the shrine.", "A pilgrim is safe on the road by custom and fed by law. Some are sent on pilgrimage as a sentence, and some are paid to go for another."),
        ["beggar/refugee"] = ("Driven from home by war, famine or plague, on the road with a bundle, children and nothing else.", "In the Ashen Years whole peoples took the road. Every race tells of the gate that opened to it, and of the one that did not."),
        ["beggar/street orphan"] = ("A child without family who lives in the street, runs errands, begs and steals, and sleeps in doorways.", "The guilds take a few as apprentices and the gangs take more. Swiftborn orphans are grown at seven and gone before a charity has met to discuss them."),
        // thief
        ["thief/cutpurse"] = ("Cuts the strings of a purse in a crowd with a small sharp blade, and is gone before it is missed.", "Works the crowd at a hanging, where another cutpurse is being hanged. Trained on a purse hung with bells."),
        ["thief/pickpocket"] = ("Lifts coins and trinkets from belts and sleeves with light fingers, often as one of a pair: one jostles, one takes.", "Children, mostly, with a master who takes the lot and feeds them. A lost ear tells the watch it is not the first offence."),
        ["thief/burglar"] = ("Breaks into houses by night, over the roof or through the shutter, with a hooked bar, a dark lantern and soft shoes.", "Breaking a house at night is hanged where the same theft by day is fined. Catfolk make the best burglars and the best night watch, and each knows it."),
        ["thief/fence"] = ("Buys stolen goods cheap and sells them on, behind the front of an honest shop.", "The law hangs the thief and fines the receiver. The fence keeps a pawnshop, an alibi and the watch captain's wife in ribbons."),
        ["thief/smuggler"] = ("Carries goods past the customs by night, in hidden coves, false bottoms and mountain paths.", "Whole coasts live by it, priest and squire included. Shoalfolk hold that the customs line is drawn on land and does not apply to them."),
        ["thief/forger"] = ("Makes false seals, deeds, letters and coin, with a steady hand, stolen models and a small press.", "A false charter has made many an abbey rich. To forge the ruler's coin is treason, and the forger is boiled."),
        ["thief/swindler"] = ("Lives by tricks: loaded dice, false relics, a sad story or a sure investment. Dressed to be trusted.", "Sells the same pig's bones as a saint in every town. An honest man cannot be cheated, the swindlers say, and they have met very few."),
        ["thief/blackmailer"] = ("Learns secrets and is paid to keep them: a letter kept, a servant bribed, a quiet word.", "The servant's trade, turned to account. It ends when the victim has nothing left, or a friend with a knife."),
        ["thief/enforcer"] = ("The hard hand of a gang: collects its dues, breaks fingers and guards its master, with a cudgel and a knife.", "Orcs and old soldiers. A gang's peace is kept by one and the watch is glad of it, most nights."),
        ["thief/poisoner"] = ("Kills for pay with a dose in the cup or the dish, and gets close as a servant, a cook or a guest.", "The weapon of the weak and of the court. The Stillfaces smell it in the cup, and the great houses hire them for exactly that."),
        ["thief/hired killer"] = ("Kills for pay with a blade, a cord or a bolt from the dark, and leaves no name. Plain clothes and a face no one remembers.", "The brotherhoods take a contract and keep it even after the client is dead. A ruler who uses them once is never sure of being the last to."),
        // bandit
        ["bandit/highwayman"] = ("Stops travellers on the road, mounted and masked, with a sword or a bow, and takes purse and horse.", "A ruined gentleman in the ballad, a deserter in fact. He is hanged at the crossroads he worked, and the ballad is sold at the hanging."),
        ["bandit/robber"] = ("One of a band that lies in wait in a wood or a pass and falls on those who come by. Ragged and armed with what was taken.", "Unpaid soldiers and landless sons. The band has a captain, shares and a law of its own, harsher than the king's."),
        ["bandit/raider"] = ("Rides or sails with a war band to strike a village, take cattle, goods and captives, and be gone before help comes.", "For the Northmen and the Grass riders a raid is a season's honest work, sung about afterwards. The people raided keep a different account."),
        ["bandit/rustler"] = ("Steals cattle, horses or sheep by night, drives them far and changes their marks.", "Among the cattle peoples a young man is not grown until he has lifted a cow from a neighbour. The neighbour's young men feel the same."),
        ["bandit/poacher"] = ("Takes the lord's game by night with snares, a bow and a quiet dog, and sells the meat or eats it.", "The village does not count it a theft, and the lord counts it worse than one. A poacher's wife sells rabbits to the warden's cook."),
        ["bandit/outlaw"] = ("Put outside the law for a crime or a debt, and living in the wild where anyone may kill him. A hood, a bow and a hunted look.", "A wolf's head: anyone may kill him and no one may feed him. The greenwood songs are about the one who was wronged, and the forest holds the others."),
        ["bandit/pirate"] = ("Takes ships at sea and raids the coasts, from a fast vessel. Armed with cutlass, axe and boarding hooks.", "The crew votes on the captain and shares by written articles. With a ruler's letter the same man is a privateer and dines with the governor."),
        ["bandit/wrecker"] = ("Lives on a dangerous coast and plunders ships that strike, and on a dark night shows a false light to bring one in.", "The shore claims what the sea gives, and no law has ever got the better of that. The prayer on such a coast is not for no wrecks, but for wrecks here."),
        ["bandit/rebel"] = ("Has taken up arms against the ruler, with a band in the hills, for a lost cause, a creed or a rival claimant. Armed with farm tools and captured weapons.", "A rebel who wins is a founder, and the chronicles are rewritten. The Ashen Years made more of them than any king did."),
    };
}
